import { z } from 'zod';
import { militaryServiceValues } from '~/constants/account/militaryServiceOptions';
import { readinessStageValues } from '~/constants/recruitment/readinessStageConfig';
import { staffingContactSourceValues } from '~/constants/staffing-contacts/staffingContactSourceConfig';

const distanceClassificationEnum = z.enum(['local', 'qrf']);

const fePriorBodySchema = z.object({
  subject: z.string().min(1),
  content: z.string().min(1),
});

// Carried through to the preview only - never edited in the form.
const feCrossPromoSchema = z.object({
  project: z.object({
    id: z.string(),
    name: z.string(),
    description: z.string(),
    locations: z.string(),
    start_date: z.string(),
    end_date: z.string(),
    public_url: z.string().nullable(),
    project_type: z.string(),
  }),
  rate_amount: z.string().nullable(),
  increased_rate_amount: z.string().nullable(),
  increased_rate_threshold: z.string().nullable(),
  nearest_location: z.string().nullable(),
  distance_classification: distanceClassificationEnum.nullable(),
});

export const promptEditorOverrideSchema = z
  .object({
    general_system_message: z.string().min(1).max(10000),
    general_user_message: z.string().min(1).max(10000),
    project_system_message: z.string().min(1).max(10000),
    project_user_message: z.string().min(1).max(10000),
    sms_general_system_message: z.string().min(1).max(10000),
    sms_general_user_message: z.string().min(1).max(10000),
    sms_project_system_message: z.string().min(1).max(10000),
    sms_project_user_message: z.string().min(1).max(10000),
    context_message_count: z.number().int().gt(0).lte(20),
    contact_first_name: z.string().min(1),
    contact_last_name: z.string(),
    contact_preferred_name: z.string(),
    contact_state: z.string(),
    contact_city: z.string(),
    contact_user_id: z.string().nullable(),
    contact_additional_languages: z.array(z.string()),
    contact_military_status: z.string(),
    contact_total_projects: z.number().int(),
    contact_source: z.enum(staffingContactSourceValues),
    contact_bio: z.string(),
    military_service: z.enum(militaryServiceValues).nullable(),
    referral_source: z.string(),
    is_referral: z.boolean(),
    referrer_user_id: z.string(),
    referrer_first_name: z.string(),
    referrer_last_name: z.string(),
    message_type: z.enum(['GENERAL', 'PROJECT']),
    campaign_selling_points: z.string().nullable(),
    campaign_latest_news: z.string().nullable(),
    campaign_custom_notes: z.string().nullable(),
    campaign_end_date: z.string(),
    target_project_name: z.string(),
    target_project_description: z.string(),
    target_project_locations: z.string(),
    target_project_start_date: z.string(),
    target_project_end_date: z.string(),
    target_project_public_url: z.string(),
    target_project_project_type: z.string(),
    rate_amount: z.string().nullable(),
    increased_rate_amount: z.string().nullable(),
    increased_rate_threshold: z.string().nullable(),
    distance_classification: distanceClassificationEnum.nullable(),
    distance_miles: z.number().nullable(),
    readiness_stage: z.enum(readinessStageValues).nullable(),
    missing_steps: z.array(z.string()),
    prior_bodies: z.array(fePriorBodySchema),
    prior_project_names: z.array(z.string()),
    cross_promos: z.array(feCrossPromoSchema),
  })
  .refine((v) => !v.is_referral || (v.referrer_user_id !== '' && v.referrer_first_name !== ''), {
    message: 'Referrer fields required when is_referral=true',
    path: ['referrer_user_id'],
  });

export type PromptEditorOverrideValues = z.infer<typeof promptEditorOverrideSchema>;
