<script setup lang="ts">
import { useForm } from 'vee-validate';
import { toTypedSchema } from '@vee-validate/zod';
import { isEqual } from 'lodash';
import { FetchError } from 'ofetch';
import { getEditorMetadata } from '~/client';
import type {
  PromptConfig,
  PromptValidationFailureResponse,
  BuildContextResponse,
  BuildContextRequest,
  PreviewPresetName,
  GetAllSystemSettingsResponse,
  StaffingContactListItem,
  UserListItem,
  ProjectStatus,
} from '~/client';
import type { ProjectListItem } from '~/types/projects/list/item';
import {
  promptEditorOverrideSchema,
  type PromptEditorOverrideValues,
} from '~/constants/validationSchemas/promptEditorOverride';
import { COLD_DEFAULTS } from '~/constants/recruitment/promptEditorColdDefaults';
import type { FePriorBody } from '~/utils/promptEditor/toPreviewContext';
import {
  tokensIn,
  unknownTokens,
  missingRequiredVariables,
  outOfScopeVariables,
  toWireChannel,
  toWireMessageType,
  type ScopeVariable,
  type PromptChannel,
} from '~/utils/promptEditor/placeholders';
import { promptValidationFailureFromError } from '~/utils/promptEditor/validationFailure';
import { toPreviewPrompt } from '~/utils/promptEditor/toPreviewPrompt';
import { usePromptDraft } from '~/composables/recruitment/usePromptDraft';
import { usePromptPreview } from '~/composables/recruitment/usePromptPreview';
import { useUpdateSettingsPrompt } from '~/mutations/system/updateSettingsPrompt';
import { useBuildContextPreview } from '~/mutations/recruitment/buildContextPreview';
import { Loader2Icon, ChevronDownIcon, CircleAlertIcon } from 'lucide-vue-next';
import { settingsFieldDescriptions } from '~/constants/recruitment/settingsFieldDescriptions';
import { fullyOnboardedReadinessStages } from '~/constants/recruitment/readinessStageConfig';
import { getProjectStatus } from '~/constants/projects';

const props = defineProps<{ settings: GetAllSystemSettingsResponse }>();

definePageMeta({ roles: ['admin'] });

const settings = computed(() => props.settings.prompt);

const { data: editorMetadata } = useQuery({
  key: () => ['prompt-editor-metadata'],
  query: () => getEditorMetadata({ composable: '$fetch' }),
});

const { isAuthenticated, userId } = useUserRole();

const validNames = computed(() => editorMetadata.value?.variables.map((v) => v.name) ?? []);

const scopeVariables = computed<ScopeVariable[]>(
  () => editorMetadata.value?.variables.map((v) => ({ name: v.name, scope: v.scope, channels: v.channels })) ?? []
);

// The active Email/SMS sub-tab. Not a form field (it picks which template pair is live), so it lives as UI state.
const channel = ref<PromptChannel>('EMAIL');

// The four (branch x channel) template pairs. Picking the active pair keeps usedNames/coverage/error all channel-aware.
function templatePair(branch: 'general' | 'project', ch: PromptChannel): [string, string] {
  if (branch === 'general') {
    return ch === 'SMS'
      ? [values.sms_general_system_message, values.sms_general_user_message]
      : [values.general_system_message, values.general_user_message];
  }
  return ch === 'SMS'
    ? [values.sms_project_system_message, values.sms_project_user_message]
    : [values.project_system_message, values.project_user_message];
}

const usedNames = computed(() => {
  const active = templatePair(toWireMessageType(values.message_type), channel.value);
  return [...new Set(active.flatMap((t) => tokensIn(t)))];
});

const { values, setValues, setFieldValue } = useForm<PromptEditorOverrideValues>({
  validationSchema: toTypedSchema(promptEditorOverrideSchema),
  initialValues: COLD_DEFAULTS,
  // Sub-tabs unmount the inactive template pair; keep their values so all four stay in the form for dirty-check/render/save.
  keepValuesOnUnmount: true,
});

function toPromptSlice(v: PromptEditorOverrideValues): PromptConfig {
  return {
    general_system_message: v.general_system_message,
    general_user_message: v.general_user_message,
    project_system_message: v.project_system_message,
    project_user_message: v.project_user_message,
    sms_general_system_message: v.sms_general_system_message,
    sms_general_user_message: v.sms_general_user_message,
    sms_project_system_message: v.sms_project_system_message,
    sms_project_user_message: v.sms_project_user_message,
    context_message_count: v.context_message_count,
  };
}

const hasHydrated = ref(false);

const previewContextReady = ref(false);
const selectedPresetName = ref<PreviewPresetName | null>('cold');
const selectedProjectLabel = ref<string | null>(null);
const selectedReferrerLabel = ref<string | null>(null);
// Secondary info shown in the picker triggers (email / project status / referrer role) for the selected item.
const selectedContactEmail = ref<string | null>(null);
const selectedProjectStatus = ref<ProjectStatus | null>(null);
const selectedReferrerRole = ref<string | null>(null);

type PreviewSource =
  | { type: 'preset'; preset_name: PreviewPresetName }
  | { type: 'contact'; contact_email: string }
  | { type: 'random_contact' };
const currentSource = ref<PreviewSource>({ type: 'preset', preset_name: 'cold' });

const contactDisplayName = computed(() => {
  const name = [values.contact_first_name, values.contact_last_name].filter(Boolean).join(' ').trim();
  return name || null;
});

const { resolvePreviewContext, isResolvingPreviewContext } = useBuildContextPreview();
// Bumped on every resolve; a slower earlier response whose stamp no longer matches is dropped so it can't overwrite a newer overlay.
const resolveStamp = ref(0);
async function buildContext(body: {
  source: PreviewSource;
  project_id_overlay?: string | null;
  referrer_user_id_overlay?: string | null;
}) {
  // Drop an overlay's label when its overlay is dropped, else the picker shows a project/referrer no longer in the context.
  if (body.project_id_overlay == null) {
    selectedProjectLabel.value = null;
    selectedProjectStatus.value = null;
  }
  if (body.referrer_user_id_overlay == null) {
    selectedReferrerLabel.value = null;
    selectedReferrerRole.value = null;
    // Picking a referrer is the only thing that makes a send a referral, so a resolve without one is never a referral.
    if (values.is_referral) setFieldValue('is_referral', false);
  }
  const stamp = ++resolveStamp.value;
  const reqBody: BuildContextRequest = {
    source: body.source,
    message_type: toWireMessageType(values.message_type),
    is_referral: values.is_referral,
    context_message_count: values.context_message_count ?? 20,
    project_id_overlay: body.project_id_overlay ?? null,
    sample_project: values.message_type === 'PROJECT' && (body.project_id_overlay ?? null) === null,
    referrer_user_id_overlay: body.referrer_user_id_overlay ?? null,
    // the resolver stamps the context's channel_strategy from this; without it every build is stamped
    // as the email channel even when the SMS sub-tab is active
    channel: toWireChannel(channel.value),
  };
  try {
    const res = await resolvePreviewContext(reqBody);
    // a newer resolve superseded this one mid-flight - drop the stale overlay
    if (stamp !== resolveStamp.value) return;
    applyContextOverlays(res);
    // Pin a random draw by resolved email so a later rebuild reuses the same person, not a new random one.
    if (body.source.type === 'random_contact' && res.resolved_contact_email) {
      currentSource.value = { type: 'contact', contact_email: res.resolved_contact_email };
    }
  } catch {
    // the mutation's onError already surfaced the toast
  }
}

function applyContextOverlays(res: BuildContextResponse) {
  const ctx = res.context;
  const c = ctx.contact;
  selectedContactEmail.value = res.resolved_contact_email ?? null;
  const overlay: Partial<PromptEditorOverrideValues> = {
    contact_first_name: c.first_name ?? '',
    contact_last_name: c.last_name ?? '',
    contact_preferred_name: c.preferred_name ?? '',
    contact_state: c.state ?? '',
    contact_city: c.city ?? '',
    contact_user_id: c.user_id ?? null,
    contact_additional_languages: c.additional_languages,
    contact_military_status: c.military_status ?? '',
    contact_total_projects: c.total_projects,
    contact_source: c.source,
    contact_bio: ctx.contact_bio ?? '',
    military_service: ctx.military_service,
    referral_source: ctx.referral_source ?? '',
    rate_amount: ctx.rate_amount,
    increased_rate_amount: ctx.increased_rate_amount,
    increased_rate_threshold: ctx.increased_rate_threshold,
    distance_classification: ctx.distance_classification,
    distance_miles: ctx.distance_miles,
    readiness_stage: ctx.readiness_stage,
    missing_steps: ctx.missing_steps,
    prior_project_names: ctx.prior_project_names,
    cross_promos: ctx.cross_promos,
  };

  // Clear must mirror populate: drop referrer/campaign fields on rebuild, else toPreviewContext ships a stale referrer/project.
  if (ctx.referrer) {
    overlay.referrer_user_id = ctx.referrer.user_id;
    overlay.referrer_first_name = ctx.referrer.first_name;
    overlay.referrer_last_name = ctx.referrer.last_name;
  } else {
    overlay.referrer_user_id = '';
    overlay.referrer_first_name = '';
    overlay.referrer_last_name = '';
  }

  if (ctx.campaign) {
    overlay.campaign_selling_points = ctx.campaign.selling_points;
    overlay.campaign_latest_news = ctx.campaign.latest_news;
    overlay.campaign_custom_notes = ctx.campaign.custom_notes;
    overlay.campaign_end_date = ctx.campaign.end_date ?? '';

    const tp = ctx.campaign.target_project;
    if (tp) {
      overlay.target_project_name = tp.name;
      overlay.target_project_description = tp.description;
      overlay.target_project_locations = tp.locations;
      overlay.target_project_start_date = tp.start_date ?? '';
      overlay.target_project_end_date = tp.end_date ?? '';
      overlay.target_project_public_url = tp.public_url ?? '';
      overlay.target_project_project_type = tp.project_type;
    } else {
      overlay.target_project_name = '';
      overlay.target_project_description = '';
      overlay.target_project_locations = '';
      overlay.target_project_start_date = '';
      overlay.target_project_end_date = '';
      overlay.target_project_public_url = '';
      overlay.target_project_project_type = '';
    }
  } else {
    overlay.campaign_selling_points = null;
    overlay.campaign_latest_news = null;
    overlay.campaign_custom_notes = null;
    overlay.campaign_end_date = '';
    overlay.target_project_name = '';
    overlay.target_project_description = '';
    overlay.target_project_locations = '';
    overlay.target_project_start_date = '';
    overlay.target_project_end_date = '';
    overlay.target_project_public_url = '';
    overlay.target_project_project_type = '';
  }

  overlay.prior_bodies = ctx.prior_bodies.map((b) => ({ subject: b.subject, content: b.content }));

  setValues(overlay, false);
}

// settings is injected by the recruitment.vue shell (gated on load) so it's always present at mount. One onMounted:
// hydrate synchronously first (before any await, so first paint isn't blocked), register the save shortcut, then the
// initial preview resolve. No watch.
onMounted(async () => {
  applyPromptSlice(settings.value);
  hasHydrated.value = true;
  window.addEventListener('keydown', onSaveShortcut);
  const stamp = ++resolveStamp.value;
  try {
    const res = await resolvePreviewContext({
      source: { type: 'preset', preset_name: 'cold' },
      message_type: 'general',
      is_referral: false,
      context_message_count: 20,
    });
    // a user action (e.g. a tab switch) during the initial resolve supersedes this cold context - don't clobber it
    if (stamp === resolveStamp.value) applyContextOverlays(res);
  } catch {
    // the mutation's onError already surfaced the toast
  } finally {
    previewContextReady.value = true;
  }
});

onUnmounted(() => window.removeEventListener('keydown', onSaveShortcut));

const savedPromptSlice = computed<PromptConfig | null>(() => settings.value ?? null);

const draftPromptSlice = computed<PromptConfig | null>(() => (settings.value ? toPromptSlice(values) : null));

// The backend skips the 20-40s sample-message/judge pass when only context_message_count changed (its validator
// diffs the eight template strings across the four email and SMS panes, not the count), so the progress stepper
// would lie - show it only when a template pane actually changed; a context-only save then shows just the
// Save-button spinner.
const templatesChanged = computed(() => {
  const saved = savedPromptSlice.value;
  const draft = draftPromptSlice.value;
  if (!saved || !draft) return false;
  return (
    saved.general_system_message !== draft.general_system_message ||
    saved.general_user_message !== draft.general_user_message ||
    saved.project_system_message !== draft.project_system_message ||
    saved.project_user_message !== draft.project_user_message ||
    saved.sms_general_system_message !== draft.sms_general_system_message ||
    saved.sms_general_user_message !== draft.sms_general_user_message ||
    saved.sms_project_system_message !== draft.sms_project_system_message ||
    saved.sms_project_user_message !== draft.sms_project_user_message
  );
});

const validSet = computed(() => new Set(validNames.value));

function pairHasUnknownTokens(systemMessage: string, userMessage: string): boolean {
  if (validSet.value.size === 0) return false; // metadata not loaded yet; don't false-block
  return (
    unknownTokens(systemMessage, validSet.value).length > 0 || unknownTokens(userMessage, validSet.value).length > 0
  );
}

function pairHasCoverageGap(
  branch: 'general' | 'project',
  ch: PromptChannel,
  systemMessage: string,
  userMessage: string
): boolean {
  if (scopeVariables.value.length === 0) return false; // metadata not loaded yet; don't false-block
  return (
    missingRequiredVariables(scopeVariables.value, branch, ch, systemMessage, userMessage).length > 0 ||
    outOfScopeVariables(scopeVariables.value, branch, ch, systemMessage, userMessage).length > 0
  );
}

// One error flag per (branch x channel) template pair: any unknown token OR coverage gap. Drives both the
// per-channel sub-tab dot and (rolled up) the per-branch message-type dot, and (rolled up further) the save gate.
function pairHasErrors(branch: 'general' | 'project', ch: PromptChannel): boolean {
  const [system, user] = templatePair(branch, ch);
  return pairHasUnknownTokens(system, user) || pairHasCoverageGap(branch, ch, system, user);
}

const branchErrors = computed(() => ({
  general: { EMAIL: pairHasErrors('general', 'EMAIL'), SMS: pairHasErrors('general', 'SMS') },
  project: { EMAIL: pairHasErrors('project', 'EMAIL'), SMS: pairHasErrors('project', 'SMS') },
}));

const generalHasErrors = computed(() => branchErrors.value.general.EMAIL || branchErrors.value.general.SMS);
const projectHasErrors = computed(() => branchErrors.value.project.EMAIL || branchErrors.value.project.SMS);

// Backend rejects unknown/out-of-scope tokens at save anyway; gating here is instant and skips the round-trip.
// All eight templates are persisted together, so an error in any hidden pair must block the save too.
const hasTemplateErrors = computed(() => generalHasErrors.value || projectHasErrors.value);

// Only the ACTIVE pair gates render/generate: broken templates on other tabs are swapped for their
// saved versions in the preview payload (toPreviewSlice), so they can't fail request validation.
const activePairUnknownTokens = computed(() => {
  if (validSet.value.size === 0) return [];
  const [system, user] = templatePair(toWireMessageType(values.message_type), channel.value);
  return [...new Set([...unknownTokens(system, validSet.value), ...unknownTokens(user, validSet.value)])];
});

const renderBlock = computed(() =>
  activePairUnknownTokens.value.length
    ? `Fix the unknown variables on this tab before generating: ${activePairUnknownTokens.value.map((n) => `{${n}}`).join(', ')}`
    : null
);

// Preview-only: broken inactive pairs fall back to saved templates. Save must keep the raw toPromptSlice.
function toPreviewSlice(v: PromptEditorOverrideValues): PromptConfig {
  const draft = toPromptSlice(v);
  const saved = savedPromptSlice.value;
  if (!saved) return draft;
  return toPreviewPrompt({
    draft,
    saved,
    messageType: toWireMessageType(v.message_type),
    channel: channel.value,
    validNames: validSet.value,
  });
}

const canSave = computed(() => {
  if (!savedPromptSlice.value || !draftPromptSlice.value) return false;
  if (hasTemplateErrors.value) return false;
  return !isEqual(savedPromptSlice.value, draftPromptSlice.value);
});

// "Unsaved" header badge: the template slice differs from the saved one, regardless of whether it's currently valid.
// Gated on hasHydrated so the badge doesn't flash before onMounted seeds the form from the saved prompt.
const hasUnsavedChanges = computed(
  () =>
    hasHydrated.value &&
    !!savedPromptSlice.value &&
    !!draftPromptSlice.value &&
    !isEqual(savedPromptSlice.value, draftPromptSlice.value)
);

// Collapsed-header "Saving Prompt" spinner badge; while it shows, the "Unsaved" badge is redundant.
const isSavingPromptBadge = computed(() => isValidating.value && !promptsOpen.value);

const { showRestoreBanner, onRestoreDraft, onDiscardDraft, clearDraft, draftSavedAt } = usePromptDraft({
  values,
  savedSlice: savedPromptSlice,
  hasHydrated,
  toPromptSlice,
  restore: (slice) => setValues(slice, false),
  userId: userId.value ?? '',
});

const draftTimeAgo = useTimeAgo(() => draftSavedAt.value ?? new Date());

const promptsOpen = ref(true);
const renderedOpen = ref(false);

const {
  renderedPrompt,
  placeholderValues,
  generatedEmail,
  generatedSms,
  isStale,
  isRendering,
  renderError,
  isGenerating,
  onGenerate,
} = usePromptPreview({
  values,
  channel,
  ready: previewContextReady,
  toPreviewSlice,
  renderBlock,
});

const { updateSettingsPrompt } = useUpdateSettingsPrompt();
// The last failed report is KEPT after the window closes so an accidental dismiss (or a jump-to-fix) never throws
// away a 30-90s, non-deterministic result. `validationOpen` shows/hides the window; `validationFailure` holds the
// report until the next save replaces it or a successful save clears it.
const validationFailure = ref<PromptValidationFailureResponse | null>(null);
const validationOpen = ref(false);
// Spans the whole gate including the transient auto-retry, so the progress strip and Save button stay steady
// across a retry instead of blinking with each underlying mutation.
const isValidating = ref(false);

const validationIssueCount = computed(() => {
  const result = validationFailure.value?.result;
  if (!result) return 0;
  if (result.stage === 'judge') return (result.judged_emails ?? []).filter((e) => !e.compliant).length;
  return (result.violations ?? []).length;
});

// 'generation' is a transient model hiccup, not a prompt defect; the backend already retried Gemini, so we
// re-run the whole gate once more before bothering the admin with the failure modal.
async function attemptSave(autoRetried: boolean) {
  try {
    await updateSettingsPrompt(toPromptSlice(values));
    clearDraft();
    validationFailure.value = null;
  } catch (err) {
    const failure = promptValidationFailureFromError(err);
    if (failure && failure.result.stage === 'generation' && !autoRetried) {
      showToastInfo('Model was briefly busy', 'Re-running validation...');
      await attemptSave(true);
      return;
    }
    if (failure) {
      validationFailure.value = failure;
      validationOpen.value = true;
    }
  }
}

async function onSave() {
  // Save persists only the template slice, so gate on canSave (template valid + changed) - not the preview-input fields the form schema also validates.
  if (!canSave.value || isValidating.value) return;
  isValidating.value = true;
  validationOpen.value = false;
  validationFailure.value = null;
  try {
    await attemptSave(false);
  } finally {
    isValidating.value = false;
  }
}

type ResetMode = 'saved' | 'default';
const pendingReset = ref<ResetMode | null>(null);

function applyPromptSlice(slice: PromptConfig) {
  setValues(
    {
      general_system_message: slice.general_system_message,
      general_user_message: slice.general_user_message,
      project_system_message: slice.project_system_message,
      project_user_message: slice.project_user_message,
      sms_general_system_message: slice.sms_general_system_message,
      sms_general_user_message: slice.sms_general_user_message,
      sms_project_system_message: slice.sms_project_system_message,
      sms_project_user_message: slice.sms_project_user_message,
      context_message_count: slice.context_message_count,
    },
    false
  );
}

function confirmReset() {
  if (pendingReset.value === 'saved' && savedPromptSlice.value) {
    applyPromptSlice(savedPromptSlice.value);
  } else if (pendingReset.value === 'default' && editorMetadata.value?.default_prompt) {
    applyPromptSlice(editorMetadata.value.default_prompt);
  }
  pendingReset.value = null;
}

// Plain <input>, not shadcn Input: its passive v-model caches the typed value and won't resync when a clamp maps back to the current value (type 99 at 20 -> stays 20, no :value change). Commit on change, not per keystroke.
function onContextCountChange(e: Event) {
  const el = e.target as HTMLInputElement;
  const raw = Number(el.value);
  const next =
    Number.isFinite(raw) && el.value.trim() !== ''
      ? Math.min(20, Math.max(1, Math.round(raw)))
      : values.context_message_count;
  setFieldValue('context_message_count', next);
  el.value = String(next);
}

function onSaveShortcut(e: KeyboardEvent) {
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 's') {
    e.preventDefault();
    if (canSave.value && !isValidating.value) onSave();
  }
}

async function onPresetSelect(name: PreviewPresetName) {
  selectedPresetName.value = name;
  currentSource.value = { type: 'preset', preset_name: name };
  await buildContext({ source: currentSource.value });
}

async function onContactSelect(contact: StaffingContactListItem) {
  selectedPresetName.value = null;
  currentSource.value = { type: 'contact', contact_email: contact.email };
  await buildContext({ source: currentSource.value });
}

async function onRandomContact() {
  selectedPresetName.value = null;
  await buildContext({ source: { type: 'random_contact' } });
}

async function onProjectSelect(project: ProjectListItem) {
  selectedProjectLabel.value = project.name;
  selectedProjectStatus.value = project.status;
  await buildContext({ source: currentSource.value, project_id_overlay: project.id });
}

async function onProjectClear() {
  await buildContext({ source: currentSource.value });
}

// Referral has no separate toggle: picking a referrer IS the referral (production never sends a referral without one).
async function onReferrerSelect(referrer: UserListItem) {
  selectedReferrerLabel.value = `${referrer.first_name} ${referrer.last_name}`.trim();
  selectedReferrerRole.value = referrer.role;
  if (!values.is_referral) setFieldValue('is_referral', true);
  await buildContext({ source: currentSource.value, referrer_user_id_overlay: referrer.id });
}

async function onReferrerClear() {
  if (values.is_referral) setFieldValue('is_referral', false);
  await buildContext({ source: currentSource.value });
}

async function onMessageTypeChange(v: 'GENERAL' | 'PROJECT') {
  setFieldValue('message_type', v);
  if (v === 'PROJECT') {
    if (values.is_referral) setFieldValue('is_referral', false);
    selectedReferrerLabel.value = null;
    selectedReferrerRole.value = null;
  } else {
    selectedProjectLabel.value = null;
    selectedProjectStatus.value = null;
    // Reset only built-in gated personas to cold on General (a picked/random onboarded contact is left alone).
    const src = currentSource.value;
    if (src.type === 'preset') {
      const stage = editorMetadata.value?.presets.find((p) => p.name === src.preset_name)?.readiness_stage;
      if (stage && fullyOnboardedReadinessStages.has(stage)) {
        selectedPresetName.value = 'cold';
        currentSource.value = { type: 'preset', preset_name: 'cold' };
      }
    }
  }
  await buildContext({ source: currentSource.value });
}

// Switching channel only swaps which template pair is live; the preview context (contact/project/referral) is
// unchanged, so no rebuild - usePromptPreview's render watcher keys on channel and re-renders the new pair.
function onChannelChange(v: string | number) {
  channel.value = v === 'SMS' ? 'SMS' : 'EMAIL';
}
async function onClearAll() {
  if (isResolvingPreviewContext.value) return;
  // Reset the persona to the cold preset and re-resolve; message_type is preserved (buildContext reads it off values),
  // so clearing the overrides doesn't yank the editor off the Project branch it's on.
  if (values.is_referral) setFieldValue('is_referral', false);
  selectedReferrerLabel.value = null;
  selectedReferrerRole.value = null;
  selectedPresetName.value = 'cold';
  currentSource.value = { type: 'preset', preset_name: 'cold' };
  await buildContext({ source: currentSource.value });
}

const activeInsert = ref<((text: string) => void) | null>(null);

function onEditorFocus(insert: (text: string) => void) {
  activeInsert.value = insert;
}

function onPriorBodiesUpdate(next: FePriorBody[]) {
  setFieldValue('prior_bodies', next);
}

// Reopenable from the save bar; the transient 'generation' retry prompt isn't a report, so clear it on close.
function closeValidationView() {
  validationOpen.value = false;
  if (validationFailure.value?.result.stage === 'generation') validationFailure.value = null;
}

function onCloseValidationFailure() {
  closeValidationView();
}

function onRetryValidation() {
  validationOpen.value = false;
  onSave();
}

// Programmatic violations carry the field id as their location (the template field name); open the templates
// collapsible, switch to that (branch x channel) sub-tab, then scroll the CodeMirror editor (its content DOM
// carries the field id) into view and focus it. Keep the report (just hide the window) so it can be reopened.
async function onJumpToField(location: string) {
  validationOpen.value = false;
  promptsOpen.value = true;
  const targetChannel: PromptChannel = location.startsWith('sms_') ? 'SMS' : 'EMAIL';
  // The "project"/"general" segment sits after the optional "sms_" prefix (e.g. sms_project_user_message).
  const branch = /^(sms_)?project_/.test(location) ? 'PROJECT' : 'GENERAL';
  if (values.message_type !== branch) await onMessageTypeChange(branch);
  if (channel.value !== targetChannel) channel.value = targetChannel;
  await nextTick();
  const field = document.getElementById(location);
  field?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  field?.focus();
}

function onValidationModalOpenChange(open: boolean) {
  if (!open) closeValidationView();
}
</script>
