import { getProjectList } from '~/client';
import { makePromptEditorSearch } from '~/queries/recruitment/promptEditorSearch';

export const useProjectSearch = makePromptEditorSearch(
  'prompt-editor-project-search',
  (searchTerm) =>
    getProjectList({ composable: '$fetch', query: { search_query: searchTerm, page: 1, size: 20 } }).then(
      (r) => r.items
    ),
  { listOnOpen: true }
);
