import type { FetchError } from 'ofetch';
import type { PromptValidationFailureResponse } from '~/client';

// The prompt save-gate returns a structured 400 ({ result: ... }) on validation failure; anything else is a plain error.
export function promptValidationFailureFromError(err: unknown): PromptValidationFailureResponse | null {
  const fetchErr = err as FetchError;
  const status = fetchErr?.statusCode ?? fetchErr?.response?.status;
  const data = fetchErr?.data ?? (fetchErr?.response as { _data?: unknown })?._data;
  if (status === 400 && !!data && typeof data === 'object' && 'result' in (data as object)) {
    return data as PromptValidationFailureResponse;
  }
  return null;
}
