<template>
  <Card>
    <CardHeader>
      <div class="flex items-center justify-between">
        <CardTitle class="text-base md:text-base">Generated Email</CardTitle>
        <Badge v-if="isStale && generated" variant="warning">Stale</Badge>
      </div>
    </CardHeader>
    <CardContent class="flex flex-col gap-4">
      <slot name="context" />
      <div v-if="!generated" class="text-muted-foreground text-sm">
        {{ isGenerating ? 'Generating with Gemini...' : 'Click Generate to call Gemini.' }}
        <div class="mt-2">
          <Button
            type="button"
            variant="default"
            :loading="isGenerating"
            :disabled="isGenerating"
            @click="$emit('generate')"
          >
            Generate
          </Button>
        </div>
      </div>
      <div v-else class="grid gap-3">
        <div>
          <div class="flex items-center justify-between">
            <span class="font-medium">Subject</span>
            <Button type="button" variant="ghost" size="sm" @click="copyField(generated.generated_subject, 'subject')">
              {{ activeCopiedField === 'subject' ? 'Copied' : 'Copy' }}
            </Button>
          </div>
          <div class="text-sm">{{ generated.generated_subject }}</div>
        </div>
        <div>
          <div class="flex items-center justify-between">
            <span class="font-medium">Content</span>
            <Button type="button" variant="ghost" size="sm" @click="copyField(generated.generated_content, 'content')">
              {{ activeCopiedField === 'content' ? 'Copied' : 'Copy' }}
            </Button>
          </div>
          <div class="bg-muted flex justify-center rounded-md border p-4 sm:p-6">
            <iframe
              ref="previewFrame"
              :srcdoc="generated.rendered_email_html"
              class="block min-h-[12rem] w-full max-w-[600px] rounded-lg border bg-white shadow-sm pointer-events-none"
              sandbox="allow-same-origin"
              title="Rendered recruitment email"
              @load="fitPreviewHeight"
            />
          </div>
        </div>
        <div class="text-xs text-muted-foreground">{{ generated.model_version }} - {{ generated.latency_ms }}ms</div>
        <div>
          <Button
            type="button"
            variant="outline"
            :loading="isGenerating"
            :disabled="isGenerating"
            @click="$emit('generate')"
          >
            Regenerate
          </Button>
        </div>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { GenerateResponse } from '~/client';

defineProps<{ generated: GenerateResponse | null; isStale: boolean; isGenerating: boolean }>();
defineEmits<{ (e: 'generate'): void }>();

const { activeCopiedField, copyField } = useCopyField();

const previewFrame = ref<HTMLIFrameElement | null>(null);

// Size the iframe to its content; reading the height requires same-origin (sandbox="allow-same-origin").
function fitPreviewHeight(): void {
  const frame = previewFrame.value;
  const doc = frame?.contentDocument;
  if (!frame || !doc) return;
  // Reset first so the frame can SHRINK on Regenerate, not only grow: a pinned height floors
  // documentElement.scrollHeight at the old viewport, so re-measuring without a reset never gets smaller.
  frame.style.height = '0px';
  const height = Math.max(doc.documentElement.scrollHeight, doc.body?.scrollHeight ?? 0);
  frame.style.height = `${height}px`;
}
</script>

<style lang="scss" scoped></style>
