<template>
  <Card>
    <CardHeader>
      <div class="flex items-center justify-between">
        <CardTitle>Generated SMS</CardTitle>
        <Badge v-if="isStale && generated" variant="warning">Stale</Badge>
      </div>
    </CardHeader>
    <CardContent class="flex flex-col gap-4">
      <slot name="context" />
      <div v-if="!generated" class="text-muted-foreground text-sm">
        {{ isGenerating ? 'Generating with Gemini...' : 'Click Generate to call Gemini.' }}
        <div class="mt-2">
          <Button
            type="button"
            variant="default"
            :loading="isGenerating"
            :disabled="isGenerating"
            @click="$emit('generate')"
          >
            Generate
          </Button>
        </div>
      </div>
      <div v-else class="grid gap-3">
        <div>
          <div class="flex items-center justify-between">
            <span class="font-medium">Body</span>
            <Button type="button" variant="ghost" size="sm" @click="copyField(generated.body, 'body')">
              {{ activeCopiedField === 'body' ? 'Copied' : 'Copy' }}
            </Button>
          </div>
          <!-- Grayed = code-appended, not model output. -->
          <div class="rounded-md border bg-muted/40 p-3 text-sm whitespace-pre-wrap">
            <span>{{ messageBody }}</span>
            <span v-if="linkLine" class="text-muted-foreground">{{ linkLine }}</span>
            <span v-if="optOutLine" class="text-muted-foreground">{{ optOutLine }}</span>
          </div>
        </div>
        <div class="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
          <span>{{ generated.char_count }} chars</span>
          <span>&middot;</span>
          <span>{{ generated.segment_count }} {{ generated.segment_count === 1 ? 'segment' : 'segments' }}</span>
          <span>&middot;</span>
          <span>{{ generated.model_version }} - {{ generated.latency_ms }}ms</span>
        </div>
        <p v-if="linkLine" class="text-xs text-muted-foreground">
          The link is added when the message is sent - each recipient gets their own tracking link to
          {{ linkTargetLabel }}.
        </p>
        <div>
          <Button
            type="button"
            variant="outline"
            :loading="isGenerating"
            :disabled="isGenerating"
            @click="$emit('generate')"
          >
            Regenerate
          </Button>
        </div>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { Badge } from '~/components/ui/badge';
import { Button } from '~/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '~/components/ui/card';
import type { SmsGenerateResponse } from '~/client';

const props = defineProps<{
  generated: SmsGenerateResponse | null;
  isStale: boolean;
  isGenerating: boolean;
  messageType: 'GENERAL' | 'PROJECT';
}>();
defineEmits<{ (e: 'generate'): void }>();

const { activeCopiedField, copyField } = useCopyField();

// The suffix carries its own leading newline, so the grayed line sits on its own line under the body.
const split = computed(() => splitSmsOptOut(props.generated?.body, props.generated?.opt_out_line));
const messageBody = computed(() => split.value.body);
const optOutLine = computed(() => split.value.optOut);

// A real send inserts a newline + a per-recipient tracking link before the opt-out line; the server
// returns a placeholder-code sample of it so the preview shows the full message without minting a link.
const linkLine = computed(() => {
  const sample = props.generated?.link_placeholder ?? '';
  return sample ? '\n' + sample : '';
});

const linkTargetLabel = computed(() =>
  props.messageType === 'PROJECT' ? "the project's public page" : 'the join page'
);
</script>
