import type { Ref } from 'vue';
import { FetchError } from 'ofetch';
import { renderPromptPreview, generatePreview } from '~/client';
import type {
  PromptConfig,
  RenderResponse,
  GenerateResponse,
  SmsGenerateResponse,
  PromptVariables,
  PromptPreviewRequest,
} from '~/client';
import type { PromptEditorOverrideValues } from '~/constants/validationSchemas/promptEditorOverride';
import { toWireChannel, toWireMessageType, type PromptChannel } from '~/utils/promptEditor/placeholders';
import { toPreviewContext } from '~/utils/promptEditor/toPreviewContext';

interface UsePromptPreviewParams {
  values: PromptEditorOverrideValues;
  // The editor's active Email/SMS sub-tab; drives which templates render/generate and which preview pane fills.
  channel: Ref<PromptChannel>;
  ready: Ref<boolean>;
  // Builds the PromptConfig the preview request ships. The caller may substitute saved templates
  // for broken inactive pairs (only the active pair is ever rendered), so this is not necessarily
  // the raw form slice.
  toPreviewSlice: (v: PromptEditorOverrideValues) => PromptConfig;
  // Mid-edit the active pair is invalid most of the time (a half-typed {token}); the backend
  // rejects that at request validation, so don't even ask. Null when rendering is possible;
  // otherwise the user-facing reason, which onGenerate surfaces as the toast.
  renderBlock: Ref<string | null>;
}

// All eight templates must be non-empty before any render/generate fires: the backend request
// carries the full PromptConfig, which is min(1) on each field. Checked on the built slice, so
// substituted saved templates count - only an empty pair on the ACTIVE tab still blocks.
function hasAllTemplateFields(slice: PromptConfig): boolean {
  return [
    slice.general_system_message,
    slice.general_user_message,
    slice.project_system_message,
    slice.project_user_message,
    slice.sms_general_system_message,
    slice.sms_general_user_message,
    slice.sms_project_system_message,
    slice.sms_project_user_message,
  ].every(Boolean);
}

// The generate response is a union (email has subject+HTML content; SMS has a plain body + char/segment count).
function isSmsGenerate(res: GenerateResponse | SmsGenerateResponse): res is SmsGenerateResponse {
  return 'body' in res;
}

function readableDetail(err: FetchError): string | null {
  const detail: unknown = err.data?.detail;
  // FastAPI request-validation errors carry detail as a list of {msg, ...} objects -
  // interpolating that raw renders unreadable JSON.
  if (Array.isArray(detail)) {
    const msgs = detail.map((d) => (d && typeof d === 'object' && 'msg' in d ? String(d.msg) : String(d)));
    return msgs.join('; ') || null;
  }
  return getErrorMessage(err);
}

export function usePromptPreview({ values, channel, ready, toPreviewSlice, renderBlock }: UsePromptPreviewParams) {
  const formChangedSinceStamp = ref(0);
  const lastGenerateStamp = ref(0);
  const hasGeneratedOnce = ref(false);
  const isStale = computed(() => hasGeneratedOnce.value && formChangedSinceStamp.value !== lastGenerateStamp.value);

  const renderedPrompt = ref<RenderResponse | null>(null);
  const placeholderValues = ref<PromptVariables | null>(null);
  const generatedEmail = ref<GenerateResponse | null>(null);
  const generatedSms = ref<SmsGenerateResponse | null>(null);
  const isRendering = ref(false);
  const renderError = ref<string | null>(null);
  const isGenerating = ref(false);

  function toRequest(slice: PromptConfig): PromptPreviewRequest {
    return {
      draft_prompt: slice,
      context: toPreviewContext(values),
      message_type: toWireMessageType(values.message_type),
      channel: toWireChannel(channel.value),
      is_referral: values.is_referral,
    };
  }

  watchDebounced(
    // Re-render when the form OR the active channel changes - switching the sub-tab swaps which templates render.
    () => [values, channel.value] as const,
    async () => {
      if (!ready.value) return;
      const slice = toPreviewSlice(values);
      if (!hasAllTemplateFields(slice)) return;
      formChangedSinceStamp.value++;
      if (renderBlock.value) {
        renderError.value = null;
        return;
      }

      const stamp = formChangedSinceStamp.value;
      isRendering.value = true;
      try {
        const res = await renderPromptPreview({
          composable: '$fetch',
          body: ref(toRequest(slice)),
        });
        // a newer edit superseded this render mid-flight - drop the stale result
        if (stamp !== formChangedSinceStamp.value) return;
        renderedPrompt.value = res;
        placeholderValues.value = res.placeholder_values;
        renderError.value = null;
      } catch (err) {
        if (stamp !== formChangedSinceStamp.value) return;
        // Inline (not a toast - too noisy mid-edit); keep prior values so the panel doesn't flicker.
        renderError.value =
          readableDetail(err as FetchError) ?? 'Preview could not be rendered with the current inputs.';
        console.warn('renderPromptPreview failed', err);
      } finally {
        // don't clear the spinner while a newer render is still in flight
        if (stamp === formChangedSinceStamp.value) isRendering.value = false;
      }
    },
    { debounce: 300, deep: true }
  );

  async function onGenerate() {
    const slice = toPreviewSlice(values);
    if (!hasAllTemplateFields(slice)) {
      showToastError('Prompt templates must be non-empty before generating');
      return;
    }
    if (renderBlock.value) {
      showToastError(renderBlock.value);
      return;
    }
    isGenerating.value = true;
    try {
      const res = await generatePreview({
        composable: '$fetch',
        body: ref(toRequest(slice)),
      });
      // The active channel decided the request; the response shape follows it (subject+HTML vs body+segments).
      if (isSmsGenerate(res)) {
        generatedSms.value = res;
      } else {
        generatedEmail.value = res;
      }
      placeholderValues.value = res.placeholder_values;
      hasGeneratedOnce.value = true;
      lastGenerateStamp.value = formChangedSinceStamp.value;
    } catch (err) {
      showToastError(err as FetchError | Error);
    } finally {
      isGenerating.value = false;
    }
  }

  return {
    renderedPrompt,
    placeholderValues,
    generatedEmail,
    generatedSms,
    isStale,
    isRendering,
    renderError,
    isGenerating,
    onGenerate,
  };
}
