import { FetchError } from 'ofetch';
import { buildContextPreview } from '~/client';
import type { BuildContextRequest, BuildContextResponse } from '~/client';

// Non-persisting resolve POST (returns the preview GenerationContext to overlay onto the form). Wrapped as a
// mutation only for the shared loading state + the onError toast - there is nothing to invalidate. Same shape as
// useGenerateCanvasserBio.
export const useBuildContextPreview = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (body: BuildContextRequest): Promise<BuildContextResponse> =>
      // ref() so the body matches the client's Ref<> overload; the plain WithRefs<> form drops the nullable overlay fields.
      buildContextPreview({ composable: '$fetch', body: ref(body) }),
    onError: (error) => showToastError(error as FetchError | Error),
  });

  return {
    resolvePreviewContext: mutateAsync,
    isResolvingPreviewContext: computed(() => asyncStatus.value === 'loading'),
  };
});
