<template>
  <Collapsible v-model:open="open" class="rounded-md border">
    <CollapsibleTrigger as-child>
      <div
        class="sticky top-0 z-20 flex min-h-[3.5rem] cursor-pointer items-center justify-between gap-2 rounded-t-md bg-background px-4 data-[state=closed]:rounded-b-md data-[state=open]:border-b"
      >
        <div class="flex items-center gap-2">
          <ChevronDownIcon :class="cn('h-4 w-4 min-h-4 min-w-4 transition-transform', !open && '-rotate-90')" />
          <span class="text-sm font-semibold">Conversation History</span>
          <span class="text-xs text-muted-foreground">
            {{ bodies.length }} prior messages, message #{{ bodies.length + 1 }}
          </span>
        </div>
      </div>
    </CollapsibleTrigger>
    <CollapsibleContent>
      <div class="flex flex-col gap-3 p-4">
        <Collapsible
          v-for="(body, idx) in bodies"
          :key="idx"
          :default-open="!body.subject && !body.content"
          class="rounded-md border"
        >
          <CollapsibleTrigger as-child>
            <div class="group flex cursor-pointer items-center justify-between gap-2 p-3">
              <div class="flex min-w-0 flex-col">
                <span class="text-xs font-semibold text-muted-foreground">Prior message {{ idx + 1 }}</span>
                <span class="truncate text-sm group-data-[state=open]:hidden">{{
                  body.subject || '(no subject)'
                }}</span>
                <span
                  v-if="snippet(body.content)"
                  class="truncate text-xs text-muted-foreground group-data-[state=open]:hidden"
                >
                  {{ snippet(body.content) }}
                </span>
              </div>
              <div class="flex shrink-0 items-center gap-2">
                <Button type="button" variant="ghost" size="sm" @click.stop="removeRow(idx)">Remove</Button>
                <ChevronDownIcon class="h-4 w-4 shrink-0 transition-transform group-data-[state=open]:rotate-180" />
              </div>
            </div>
          </CollapsibleTrigger>
          <CollapsibleContent>
            <div class="flex flex-col gap-2 p-3 pt-0">
              <div class="flex flex-col gap-1">
                <Label :for="`prior-subject-${idx}`" class="text-xs text-muted-foreground">Subject</Label>
                <Input
                  :id="`prior-subject-${idx}`"
                  :model-value="body.subject"
                  placeholder="Subject line"
                  @update:model-value="(v) => updateField(idx, 'subject', v)"
                />
              </div>
              <div class="flex flex-col gap-1">
                <Label :for="`prior-content-${idx}`" class="text-xs text-muted-foreground"
                  >Content (supports HTML)</Label
                >
                <Textarea
                  :id="`prior-content-${idx}`"
                  :model-value="body.content"
                  placeholder="Message body (HTML allowed)"
                  rows="6"
                  class="resize-y font-mono text-xs"
                  @update:model-value="(v) => updateField(idx, 'content', v)"
                />
              </div>
              <div v-if="body.content" class="flex flex-col gap-1">
                <span class="text-xs text-muted-foreground">Preview</span>
                <div
                  class="prose prose-sm max-h-[40rem] max-w-none overflow-y-auto rounded-md border bg-muted/30 p-2 text-sm"
                  v-html="sanitizeHtml(body.content)"
                />
              </div>
            </div>
          </CollapsibleContent>
        </Collapsible>
        <Button type="button" variant="outline" size="sm" class="self-start" @click="addRow">
          Add prior message
        </Button>
      </div>
    </CollapsibleContent>
  </Collapsible>
</template>

<script setup lang="ts">
import { ChevronDownIcon } from 'lucide-vue-next';
import { cn } from '@/lib/utils';
import type { FePriorBody } from '~/utils/promptEditor/toPreviewContext';

const props = defineProps<{ bodies: FePriorBody[] }>();
const emit = defineEmits<{ (e: 'update:bodies', v: FePriorBody[]): void }>();

const open = ref(false);

function snippet(html: string): string {
  const text = html
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > 80 ? text.slice(0, 80) + '...' : text;
}

function addRow() {
  emit('update:bodies', [...props.bodies, { subject: '', content: '' }]);
}

function removeRow(idx: number) {
  emit(
    'update:bodies',
    props.bodies.filter((_, i) => i !== idx)
  );
}

function updateField(idx: number, key: keyof FePriorBody, value: string | number) {
  const next = [...props.bodies];
  next[idx] = { ...next[idx], [key]: String(value) };
  emit('update:bodies', next);
}
</script>

<style lang="scss" scoped></style>
