<template>
  <div>
    <div
      ref="wrapperEl"
      :class="
        cn(
          'w-full rounded-md border border-input bg-background text-sm ring-offset-background focus-within:outline-none focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2',
          props.textareaClass
        )
      "
    />

    <p v-if="unknown.length" class="mt-1 text-xs text-destructive">
      {{ unknown.length === 1 ? 'Unknown variable:' : 'Unknown variables:' }}
      {{ unknownDisplay }}<template v-if="suggestion"> &mdash; did you mean {{ '{' + suggestion + '}' }}?</template>
    </p>
  </div>
</template>

<script setup lang="ts">
import type { HTMLAttributes } from 'vue';
import { cn } from '@/components/ui/utils';
import { EditorState, RangeSetBuilder, StateEffect, StateField, type Extension } from '@codemirror/state';
import { Decoration, type DecorationSet, EditorView, ViewPlugin, type ViewUpdate, keymap } from '@codemirror/view';
import { defaultKeymap, history, historyKeymap } from '@codemirror/commands';
import { closestName, splitTemplate, unknownTokens } from '~/utils/promptEditor/placeholders';

// inheritAttrs:false: vee-validate's componentField onInput/onChange land on our root div, read event.target.value -> undefined, and wipe the field (1Password triggers it). Bind model-value explicitly.
defineOptions({ inheritAttrs: false });

const props = defineProps<{
  modelValue?: string;
  validNames: string[];
  id?: string;
  rows?: number | string;
  textareaClass?: HTMLAttributes['class'];
}>();

const emits = defineEmits<{
  (e: 'update:modelValue', payload: string): void;
  (e: 'focus', insert: (text: string) => void): void;
}>();

// valid-name set lives in CM state (StateField) so decorations update after mount when metadata loads async.
const setValidNamesEffect = StateEffect.define<Set<string>>();

const validNamesField = StateField.define<Set<string>>({
  create: () => new Set(props.validNames),
  update(value, tr) {
    for (const e of tr.effects) if (e.is(setValidNamesEffect)) return e.value;
    return value;
  },
});

const knownMark = Decoration.mark({ class: 'cm-token-known' });
const unknownMark = Decoration.mark({ class: 'cm-token-unknown' });

function buildDecorations(view: EditorView): DecorationSet {
  const valid = view.state.field(validNamesField);
  const builder = new RangeSetBuilder<Decoration>();
  const text = view.state.doc.toString();
  let pos = 0;
  for (const seg of splitTemplate(text)) {
    const start = pos;
    pos += seg.value.length;
    if (!seg.token) continue;
    builder.add(start, pos, valid.has(seg.name) ? knownMark : unknownMark);
  }
  return builder.finish();
}

const tokenHighlighter = ViewPlugin.fromClass(
  class {
    decorations: DecorationSet;
    constructor(view: EditorView) {
      this.decorations = buildDecorations(view);
    }
    update(u: ViewUpdate) {
      if (u.docChanged || u.transactions.some((tr) => tr.effects.some((e) => e.is(setValidNamesEffect)))) {
        this.decorations = buildDecorations(u.view);
      }
    }
  },
  { decorations: (v) => v.decorations }
);

const editorTheme = EditorView.theme({
  '&': {
    fontSize: '0.875rem',
    backgroundColor: 'transparent',
    color: 'hsl(var(--foreground))',
  },
  '&.cm-focused': { outline: 'none' },
  '.cm-scroller': {
    fontFamily: 'ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace',
    lineHeight: '1.5',
    overflow: 'auto',
  },
  '.cm-content': {
    padding: '0.5rem 0.75rem',
    caretColor: 'hsl(var(--foreground))',
  },
  '.cm-line': { padding: '0' },
  '.cm-cursor, .cm-dropCursor': { borderLeftColor: 'hsl(var(--foreground))' },
  '&.cm-focused .cm-selectionBackground, .cm-selectionBackground, ::selection': {
    backgroundColor: 'hsl(var(--accent))',
  },
  '.cm-token-known': { color: '#16a34a', fontWeight: '500' },
  '.cm-token-unknown': {
    color: 'hsl(var(--destructive))',
    textDecoration: 'underline wavy',
  },
});

// CM injects its theme into a shadow-less host, so a plain .dark descendant selector works (green-400).
const darkTokenTheme = EditorView.baseTheme({
  '.dark .cm-token-known': { color: '#4ade80' },
});

const minHeightTheme = computed<Extension>(() => {
  const cls = props.textareaClass;
  const raw = Array.isArray(cls) ? cls.join(' ') : typeof cls === 'string' ? cls : '';
  const match = raw.match(/min-h-\[([^\]]+)\]/);
  const minHeight = match ? match[1] : '20rem';
  return EditorView.theme({ '.cm-content, .cm-gutter': { minHeight } });
});

const wrapperEl = ref<HTMLDivElement | null>(null);
let view: EditorView | null = null;

// Guards the Vue->CM writeback from echoing back update:modelValue (feedback loop / cursor reset).
let syncingFromProp = false;

function insertAtCursor(text: string): void {
  if (!view) return;
  // replaceSelection is undoable and fires the updateListener, so v-model + Ctrl+Z both work.
  view.dispatch(view.state.replaceSelection(text));
  view.focus();
}

defineExpose({ insertAtCursor });

function createView() {
  if (!wrapperEl.value) return;
  const state = EditorState.create({
    doc: props.modelValue ?? '',
    extensions: [
      history(),
      keymap.of([...defaultKeymap, ...historyKeymap]),
      EditorView.lineWrapping,
      EditorView.contentAttributes.of({
        autocomplete: 'off',
        autocorrect: 'off',
        autocapitalize: 'off',
        spellcheck: 'false',
        'data-1p-ignore': '',
        'data-lpignore': 'true',
        'data-form-type': 'other',
      }),
      validNamesField,
      tokenHighlighter,
      editorTheme,
      darkTokenTheme,
      minHeightTheme.value,
      EditorView.updateListener.of((u) => {
        if (u.docChanged && !syncingFromProp) emits('update:modelValue', u.state.doc.toString());
        if (u.focusChanged && u.view.hasFocus) emits('focus', insertAtCursor);
      }),
    ],
  });
  view = new EditorView({ state, parent: wrapperEl.value });
  if (props.id) view.contentDOM.id = props.id;
}

onMounted(() => {
  if (import.meta.client) createView();
});

onUnmounted(() => {
  view?.destroy();
  view = null;
});

watch(
  () => props.validNames,
  (next) => {
    view?.dispatch({ effects: setValidNamesEffect.of(new Set(next)) });
  },
  { deep: true }
);

// Replace only when next differs from the doc, else typing resets the cursor / loops.
watch(
  () => props.modelValue,
  (next) => {
    if (!view) return;
    const current = view.state.doc.toString();
    if ((next ?? '') === current) return;
    syncingFromProp = true;
    view.dispatch({
      changes: { from: 0, to: view.state.doc.length, insert: next ?? '' },
    });
    syncingFromProp = false;
  }
);

const validSet = computed(() => new Set(props.validNames));
const unknown = computed(() => unknownTokens(props.modelValue, validSet.value));
const unknownDisplay = computed(() =>
  unknown.value
    .slice(0, 5)
    .map((n) => `{${n}}`)
    .join(', ')
);
const suggestion = computed(() =>
  unknown.value.length === 1 ? closestName(unknown.value[0], props.validNames) : null
);
</script>
