<template>
  <div class="flex flex-col gap-1.5">
    <p v-if="label" class="text-sm font-medium">{{ label }}</p>
    <p v-if="description" class="text-xs text-muted-foreground">{{ description }}</p>
    <Popover v-model:open="open">
      <PopoverAnchor class="relative">
        <PopoverTrigger as-child>
          <Button
            variant="outline"
            role="combobox"
            :aria-expanded="open"
            :disabled="disabled"
            class="w-full h-10 justify-between font-normal"
          >
            <span :class="['flex min-w-0 flex-1 items-center gap-2', selectedLabel ? '' : 'text-muted-foreground']">
              <template v-if="selectedLabel"
                ><slot name="selected"
                  ><span class="truncate">{{ selectedLabel }}</span></slot
                ></template
              >
              <template v-else
                ><span class="truncate">{{ placeholder }}</span></template
              >
            </span>
            <ChevronsUpDownIcon v-if="!clearable || !selectedLabel" class="ml-2 h-4 w-4 shrink-0 opacity-50" />
            <span v-else class="ml-2 h-4 w-4 shrink-0" />
          </Button>
        </PopoverTrigger>
        <!-- Clear lives on the trigger (not as an in-list item) to match the repo's combobox pattern (AppComboboxQuery). -->
        <XIcon
          v-if="clearable && selectedLabel"
          class="absolute right-3 top-[0.75rem] h-4 w-4 shrink-0 cursor-pointer opacity-50 hover:opacity-100"
          @click.stop.prevent="onClear"
        />
      </PopoverAnchor>
      <PopoverContent class="w-[var(--reka-popover-trigger-width)] p-0">
        <Command>
          <!-- Bind ListboxFilter to our own term, NOT Command's filterState.search, so Command's client filter stays OFF: it's server-side search, so a name match whose item value is an email must still render. -->
          <div class="flex items-center border-b px-3">
            <SearchIcon class="mr-2 h-4 w-4 shrink-0 opacity-50" />
            <ListboxFilter
              v-model="searchTerm"
              auto-focus
              :placeholder="placeholder"
              class="flex h-10 w-full bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground"
            />
          </div>
          <CommandList>
            <p
              v-if="!listOnOpen && searchTerm.length === 0"
              class="py-6 px-4 text-center text-sm text-muted-foreground"
            >
              Start typing to search.
            </p>
            <p v-else-if="isSearching" class="py-6 px-4 text-center text-sm text-muted-foreground">Searching...</p>
            <p v-else-if="(items ?? []).length === 0" class="py-6 px-4 text-center text-sm text-muted-foreground">
              No matches.
            </p>
            <CommandGroup v-else>
              <CommandItem
                v-for="item in items ?? []"
                :key="itemKey(item)"
                :value="itemValue(item)"
                class="cursor-pointer"
                @select="onSelect(item)"
              >
                <slot :item="item" />
              </CommandItem>
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  </div>
</template>

<script setup lang="ts" generic="T">
import type { Ref } from 'vue';
import { ChevronsUpDownIcon, SearchIcon, XIcon } from 'lucide-vue-next';
import { ListboxFilter, PopoverAnchor } from 'reka-ui';

const props = defineProps<{
  placeholder: string;
  searchFn: (term: Ref<string>) => { data: Ref<T[] | undefined>; asyncStatus: Readonly<Ref<'idle' | 'loading'>> };
  itemKey: (item: NoInfer<T>) => string | number;
  itemValue: (item: NoInfer<T>) => string;
  selectedLabel?: string | null;
  clearable?: boolean;
  label?: string;
  description?: string;
  // Server search supports an empty term, so list results as soon as the popover opens instead of gating on first keystroke.
  listOnOpen?: boolean;
  disabled?: boolean;
}>();

const emit = defineEmits<{ (e: 'select', item: T): void; (e: 'clear'): void }>();

defineSlots<{ default(props: { item: NoInfer<T> }): unknown; selected(): unknown }>();

const open = ref(false);
const searchTerm = ref('');
const debouncedTerm = ref('');
watchDebounced(searchTerm, (v) => (debouncedTerm.value = v), { debounce: 300 });

const { data: items, asyncStatus } = props.searchFn(debouncedTerm);

// Debounced term lags the keystroke; stay on "Searching..." instead of flashing "No matches.".
const isSearching = computed(() => asyncStatus.value === 'loading' || debouncedTerm.value !== searchTerm.value);

function onSelect(item: T) {
  emit('select', item);
  open.value = false;
  searchTerm.value = '';
}

function onClear() {
  emit('clear');
  open.value = false;
  searchTerm.value = '';
}
</script>
