<template>
  <div class="hidden xl:block sticky top-4 self-start">
    <div class="rounded-md border bg-background p-3">
      <h2 class="text-sm font-semibold mb-2">Variables</h2>
      <PromptEditorVariableList v-bind="listProps" @insert="onInsert" />
    </div>
  </div>

  <div class="xl:hidden">
    <Sheet v-model:open="sheetOpen">
      <SheetTrigger as-child>
        <Button type="button" variant="outline" size="sm">Variables</Button>
      </SheetTrigger>
      <SheetContent side="right" class="overflow-y-auto">
        <SheetHeader>
          <SheetTitle>Variables</SheetTitle>
        </SheetHeader>
        <div class="pt-2">
          <PromptEditorVariableList v-bind="listProps" @insert="onInsert" />
        </div>
      </SheetContent>
    </Sheet>
  </div>
</template>

<script setup lang="ts">
import type { PromptVariables, VariableSchema } from '~/client';
import type { PromptChannel } from '~/utils/promptEditor/placeholders';

const props = defineProps<{
  variables: VariableSchema[];
  placeholderValues: PromptVariables | null;
  hasActiveField: boolean;
  messageType: 'GENERAL' | 'PROJECT';
  channel: PromptChannel;
  usedNames: string[];
}>();

const emit = defineEmits<{
  (e: 'insert', name: string): void;
}>();

function onInsert(name: string): void {
  emit('insert', name);
}

// Desktop column and mobile sheet render the same list; bundle the props so a change is one edit, not two.
const listProps = computed(() => ({
  variables: props.variables,
  placeholderValues: props.placeholderValues,
  hasActiveField: props.hasActiveField,
  messageType: props.messageType,
  channel: props.channel,
  usedNames: props.usedNames,
}));

const sheetOpen = ref(false);
</script>
