<template>
  <div class="rounded-md border">
    <div class="flex items-center justify-between border-b px-3 py-2">
      <span class="text-xs text-muted-foreground">{{ selected.length }} of {{ options.length }} selected</span>
      <Button
        v-if="selected.length"
        type="button"
        variant="ghost"
        size="sm"
        class="h-auto px-2 py-0 text-xs"
        @click="clear"
      >
        Clear
      </Button>
    </div>
    <!-- Plain roving-tabindex listbox (not reka ListboxRoot): reka focus-scrolls the highlighted row whenever the
         model-value is rewritten out-of-band (every preview rebuild), which jumped the page. Here .focus() only fires
         from the keydown handler, never on a value change, so a rebuild can't scroll the page. -->
    <div
      ref="listboxRef"
      role="listbox"
      aria-multiselectable="true"
      aria-label="Missing onboarding steps"
      class="max-h-[28rem] overflow-auto p-1 outline-none"
      @keydown="onKeydown"
    >
      <div
        v-for="(opt, idx) in options"
        :key="opt.value"
        role="option"
        :tabindex="idx === rovingIdx ? 0 : -1"
        :aria-selected="selectedSet.has(opt.value)"
        class="flex cursor-pointer items-start gap-2 rounded-md p-2 transition-colors hover:bg-accent focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring aria-selected:bg-accent"
        @click="toggle(opt.value, idx)"
      >
        <Checkbox
          :model-value="selectedSet.has(opt.value)"
          :tabindex="-1"
          class="pointer-events-none mt-0.5 shrink-0"
        />
        <span class="text-sm leading-snug">{{ opt.label }}</span>
      </div>
      <p v-if="!options.length" class="p-2 text-sm text-muted-foreground">No steps available.</p>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { ComponentFieldBindingObject } from 'vee-validate';

const props = defineProps<{
  items: SelectItem<string>[];
  componentField: ComponentFieldBindingObject;
}>();

// Wire value is the label string; drop any null-valued option so keys/membership stay plain strings.
const options = computed(() =>
  props.items.flatMap((i) => (i.value == null ? [] : [{ label: i.name ?? i.value, value: i.value }]))
);

const selected = computed<string[]>({
  get: () => (Array.isArray(props.componentField?.modelValue) ? (props.componentField.modelValue as string[]) : []),
  set: (v) => props.componentField?.onChange?.(v),
});

const selectedSet = computed(() => new Set(selected.value));

const listboxRef = useTemplateRef<HTMLElement>('listboxRef');
const focusedIdx = ref(0);
// Clamp the bound index so exactly one row stays tab-reachable even if the option set ever shrinks.
const rovingIdx = computed(() => Math.min(focusedIdx.value, Math.max(0, options.value.length - 1)));

// Rebuild the selection in option order so the wire value stays stable regardless of toggle order.
function toggle(value: string, idx: number) {
  focusedIdx.value = idx;
  const next = new Set(selected.value);
  if (next.has(value)) next.delete(value);
  else next.add(value);
  selected.value = options.value.filter((o) => next.has(o.value)).map((o) => o.value);
}

function clear() {
  selected.value = [];
}

// Wait a tick so the new tabindex=0 lands before we focus the row.
function focusRow(idx: number) {
  const rows = listboxRef.value?.querySelectorAll<HTMLElement>('[role="option"]');
  if (!rows || rows.length === 0) return;
  const clamped = Math.max(0, Math.min(idx, rows.length - 1));
  focusedIdx.value = clamped;
  nextTick(() => listboxRef.value?.querySelectorAll<HTMLElement>('[role="option"]')[clamped]?.focus());
}

function onKeydown(e: KeyboardEvent) {
  switch (e.key) {
    case 'ArrowDown':
      e.preventDefault();
      focusRow(focusedIdx.value + 1);
      break;
    case 'ArrowUp':
      e.preventDefault();
      focusRow(focusedIdx.value - 1);
      break;
    case 'Home':
      e.preventDefault();
      focusRow(0);
      break;
    case 'End':
      e.preventDefault();
      focusRow(options.value.length - 1);
      break;
    case ' ':
    case 'Enter':
      e.preventDefault();
      {
        const opt = options.value[focusedIdx.value];
        if (opt) toggle(opt.value, focusedIdx.value);
      }
      break;
  }
}
</script>

<style lang="scss" scoped></style>
