<template>
  <Dialog :open="open" @update:open="$emit('update:open', $event)">
    <DialogContent class="max-h-[85vh] overflow-y-auto sm:max-w-2xl" @interact-outside="(e) => e.preventDefault()">
      <DialogHeader>
        <DialogTitle>{{ title }}</DialogTitle>
        <DialogDescription>{{ description }}</DialogDescription>
      </DialogHeader>

      <Alert v-if="isTransient" variant="info">
        <RefreshCwIcon />
        <AlertTitle>The model was briefly unavailable</AlertTitle>
        <AlertDescription>
          We generate sample emails to check your prompt, and the writing model timed out doing that - we already
          retried once automatically. Your changes are still here; give it another try in a moment.
        </AlertDescription>
      </Alert>

      <div v-else class="flex flex-col gap-6">
        <Card
          v-for="group in concernGroups"
          :key="`${group.branch}-${group.channel}`"
          class="border-l-4"
          :class="group.severity === 'warning' ? 'border-l-yellow-500' : 'border-l-red-500'"
        >
          <CardHeader class="pb-3">
            <div class="flex items-start justify-between gap-3">
              <CardTitle class="text-base">{{ group.branchLabel }} recruitment prompt</CardTitle>
              <span
                class="shrink-0 whitespace-nowrap rounded-full px-2.5 py-0.5 text-xs font-medium"
                :class="
                  group.severity === 'warning'
                    ? 'bg-yellow-100 text-yellow-800 ring-1 ring-yellow-300'
                    : 'bg-red-100 text-red-700 ring-1 ring-red-200'
                "
              >
                {{ group.severity === 'warning' ? 'Warning' : 'Must fix' }}
              </span>
            </div>
          </CardHeader>
          <CardContent class="flex flex-col gap-3">
            <ul class="flex flex-col gap-3">
              <li v-for="(concern, i) in group.concerns" :key="i" class="flex items-start gap-3">
                <span
                  class="mt-0.5 flex size-7 shrink-0 items-center justify-center rounded-full"
                  :class="concern.severity === 'warning' ? 'bg-yellow-100' : 'bg-red-100'"
                >
                  <component
                    :is="concern.severity === 'warning' ? TriangleAlertIcon : CircleAlertIcon"
                    class="size-4"
                    :class="concern.severity === 'warning' ? 'text-yellow-800' : 'text-red-700'"
                  />
                </span>
                <div class="min-w-0 pt-0.5">
                  <p class="text-sm font-medium leading-snug text-foreground">{{ concern.text }}</p>
                  <p v-if="concern.meta" class="mt-0.5 text-xs text-muted-foreground">{{ concern.meta }}</p>
                </div>
              </li>
            </ul>
            <div class="mt-1 flex justify-end">
              <Button
                type="button"
                variant="outline"
                size="sm"
                :prepend-icon="PencilIcon"
                @click="$emit('jump', group.editTarget)"
              >
                Edit the {{ group.branchLabel }} prompt
              </Button>
            </div>
          </CardContent>
        </Card>

        <details v-if="evidenceEmails.length" class="rounded-md border bg-card">
          <summary class="cursor-pointer select-none px-4 py-3 text-sm font-medium hover:bg-muted/50">
            See the {{ evidenceEmails.length === 1 ? 'flagged message' : `${evidenceEmails.length} flagged messages` }}
            the AI wrote
          </summary>
          <div class="border-t p-4">
            <div v-for="(email, i) in evidenceEmails" :key="`${email.channel}-${email.label}`">
              <Separator v-if="i > 0" class="my-4" />
              <div class="flex items-center gap-2">
                <p class="text-sm font-medium">{{ email.label }}</p>
                <span class="shrink-0 rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground">
                  {{ email.channel === 'sms' ? 'SMS' : 'Email' }}
                </span>
              </div>
              <p class="mt-2 text-xs uppercase tracking-wide text-muted-foreground">What it wrote</p>
              <p v-if="email.subject" class="text-xs text-muted-foreground">
                Subject: <span class="text-foreground">{{ email.subject }}</span>
              </p>
              <pre
                v-if="email.channel === 'sms'"
                class="mt-1 max-h-60 overflow-y-auto whitespace-pre-wrap rounded-md bg-muted/40 p-3 text-xs text-foreground"
                >{{ email.content }}</pre
              >
              <div
                v-else
                class="prose prose-sm mt-1 max-h-60 max-w-none overflow-y-auto"
                v-html="sanitizeHtml(email.content)"
              />
              <p class="mt-3 text-xs uppercase tracking-wide text-muted-foreground">The facts it was given</p>
              <pre class="mt-1 max-h-60 overflow-y-auto whitespace-pre-wrap rounded-md bg-muted/40 p-3 text-xs">{{
                email.facts_payload
              }}</pre>
            </div>
          </div>
        </details>
      </div>

      <DialogFooter>
        <Button type="button" variant="ghost" @click="$emit('close')">Close</Button>
        <Button v-if="isTransient" type="button" @click="$emit('retry')">Try again</Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { buildConcernGroups } from '~/constants/recruitment/promptValidationRuleConfig';
import { CircleAlertIcon, PencilIcon, RefreshCwIcon, TriangleAlertIcon } from 'lucide-vue-next';
import type { PromptValidationFailureResponse } from '~/client';

const props = defineProps<{ failure: PromptValidationFailureResponse; open: boolean }>();
defineEmits<{
  (e: 'close'): void;
  (e: 'retry'): void;
  (e: 'jump', location: string): void;
  (e: 'update:open', v: boolean): void;
}>();

const isTransient = computed(() => props.failure.result.stage === 'generation');
const isJudge = computed(() => props.failure.result.stage === 'judge');

const judgedEmails = computed(() => props.failure.result.judged_emails ?? []);
const failingEmails = computed(() => judgedEmails.value.filter((e) => !e.compliant));
const total = computed(() => judgedEmails.value.length);
const violationCount = computed(() => (props.failure.result.violations ?? []).length);

const concernGroups = computed(() => buildConcernGroups(props.failure.result));
const evidenceEmails = computed(() => (isJudge.value ? failingEmails.value : []));

const title = computed(() => {
  if (isTransient.value) return "The check couldn't finish";
  if (isJudge.value) return 'Your prompt needs changes';
  return 'Fix the prompt before saving';
});
const description = computed(() => {
  if (isTransient.value) return "The writing model was briefly unavailable - this isn't a problem with your prompt.";
  if (isJudge.value)
    return `${failingEmails.value.length} of ${total.value} sample messages had problems. Fix the flagged prompt below, then save again.`;
  return `${violationCount.value} ${violationCount.value === 1 ? 'issue' : 'issues'} must be fixed before this prompt can be saved.`;
});
</script>

<style lang="scss" scoped></style>
