import { ref, computed } from 'vue';

// useClipboard's `copied` self-resets to false after `copiedDuring`, so the label reverts without a watcher.
export function useCopyField() {
  const { copy, copied } = useClipboard({ copiedDuring: 1500 });
  const copiedField = ref<string | null>(null);
  function copyField(text: string, field: string) {
    copy(text);
    copiedField.value = field;
  }
  const activeCopiedField = computed(() => (copied.value ? copiedField.value : null));
  return { activeCopiedField, copyField };
}
