import type { UseQueryReturn } from '@pinia/colada';
import type { Ref } from 'vue';

// Shared typeahead useQuery for the prompt-editor pickers; each caller passes its endpoint fetcher + cache-key prefix.
// listOnOpen fires the query on an empty term too, so the picker shows a default first page the moment it opens
// (project + referrer). Contacts omit it and stay type-to-search.
type PromptEditorSearch<T> = (searchTerm: Ref<string>) => UseQueryReturn<T[]>;

export function makePromptEditorSearch<T>(
  keyPrefix: string,
  fetcher: (searchTerm: string) => Promise<T[]>,
  options?: { listOnOpen?: boolean }
): PromptEditorSearch<T> {
  return function usePromptEditorSearch(searchTerm: Ref<string>): UseQueryReturn<T[]> {
    return useQuery<T[]>({
      key: () => [keyPrefix, searchTerm.value],
      query: () => fetcher(searchTerm.value),
      enabled: () => options?.listOnOpen || searchTerm.value.length > 0,
      staleTime: 30_000,
    });
  };
}
