import type { PromptConfig } from '~/client';
import { unknownTokens, type PromptChannel } from './placeholders';

type TemplateKey =
  | 'general_system_message'
  | 'general_user_message'
  | 'project_system_message'
  | 'project_user_message'
  | 'sms_general_system_message'
  | 'sms_general_user_message'
  | 'sms_project_system_message'
  | 'sms_project_user_message';

const TEMPLATE_PAIRS: Record<'general' | 'project', Record<PromptChannel, [TemplateKey, TemplateKey]>> = {
  general: {
    EMAIL: ['general_system_message', 'general_user_message'],
    SMS: ['sms_general_system_message', 'sms_general_user_message'],
  },
  project: {
    EMAIL: ['project_system_message', 'project_user_message'],
    SMS: ['sms_project_system_message', 'sms_project_user_message'],
  },
};

function pairBlocksPreview(system: string, user: string, validNames: Set<string>): boolean {
  if (!system || !user) return true;
  // An empty registry means the editor metadata hasn't loaded - don't false-block on it.
  if (validNames.size === 0) return false;
  return unknownTokens(system, validNames).length > 0 || unknownTokens(user, validNames).length > 0;
}

// The preview endpoints validate the whole PromptConfig but only ever render the active
// (message type x channel) pair - so a broken template on another tab must not block previewing
// this one. Inactive pairs that would fail request validation (empty field or unknown
// placeholder) are swapped for their saved versions, which passed the same validation at save
// time. The active pair always ships as drafted so the preview reflects what's on screen.
export function toPreviewPrompt(params: {
  draft: PromptConfig;
  saved: PromptConfig;
  messageType: 'general' | 'project';
  channel: PromptChannel;
  validNames: Set<string>;
}): PromptConfig {
  const { draft, saved, messageType, channel, validNames } = params;
  const result: PromptConfig = { ...draft };
  for (const branch of ['general', 'project'] as const) {
    for (const ch of ['EMAIL', 'SMS'] as const) {
      if (branch === messageType && ch === channel) continue;
      const [systemKey, userKey] = TEMPLATE_PAIRS[branch][ch];
      if (pairBlocksPreview(draft[systemKey], draft[userKey], validNames)) {
        result[systemKey] = saved[systemKey];
        result[userKey] = saved[userKey];
      }
    }
  }
  return result;
}
