// Placeholders are {snake_case_name}; the valid set = keys of PromptVariables. {{ and }} are str.format() escaped literals, not tokens.

import type { RecruitmentChannel } from '~/client';

export type TemplateSegment = { token: false; value: string } | { token: true; name: string; value: string };

// Matches an escaped `{{` or `}}` OR a single `{name}` placeholder, scanned left to right. Because
// `{{`/`}}` are matched (and skipped) before their inner characters, an escaped `{{name}}` never
// yields a token. A trailing format spec/conversion is captured INTO the name ({rate_amount:>10} ->
// "rate_amount:>10") so it surfaces as an unknown token, matching the backend's bare-{name}-only rule.
const SCAN_PATTERN = /\{\{|\}\}|\{([a-z_]+(?:[:!][^}]*)?)\}/g;

export function splitTemplate(text: string | null | undefined): TemplateSegment[] {
  if (!text) return [];
  const segments: TemplateSegment[] = [];
  let last = 0;
  SCAN_PATTERN.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = SCAN_PATTERN.exec(text)) !== null) {
    if (m[1] === undefined) continue;
    if (m.index > last) segments.push({ token: false, value: text.slice(last, m.index) });
    segments.push({ token: true, name: m[1], value: m[0] });
    last = m.index + m[0].length;
  }
  if (last < text.length) segments.push({ token: false, value: text.slice(last) });
  return segments;
}

export function tokensIn(text: string | null | undefined): string[] {
  const names: string[] = [];
  for (const seg of splitTemplate(text)) if (seg.token) names.push(seg.name);
  return names;
}

// A general send can carry a referral, a project send never does - so exclude project-scoped vars
// from the general branch and referral vars from the project branch. The channel narrows it further:
// each variable carries the channels it's valid in, so an SMS template hides the email-only ones.
export type PromptVariableScope = 'contact' | 'campaign' | 'project' | 'referral' | 'onboarding';
const ALL_SCOPES: PromptVariableScope[] = ['contact', 'campaign', 'project', 'referral', 'onboarding'];

export type PromptChannel = 'EMAIL' | 'SMS';

// The editor's message-type control is uppercase; the wire value (and this module's `branch`) is lowercase.
export function toWireMessageType(messageType: 'GENERAL' | 'PROJECT'): 'general' | 'project' {
  return messageType === 'PROJECT' ? 'project' : 'general';
}

// The editor's channel control is uppercase; the wire value (matching each variable's `channels`) is lowercase.
export function toWireChannel(channel: PromptChannel): RecruitmentChannel {
  return channel === 'SMS' ? 'sms' : 'email';
}

export interface ScopeVariable {
  name: string;
  scope: PromptVariableScope;
  channels: RecruitmentChannel[];
}

const BRANCH_SCOPES: Record<'general' | 'project', Set<PromptVariableScope>> = {
  general: new Set(ALL_SCOPES.filter((s) => s !== 'project')),
  project: new Set(ALL_SCOPES.filter((s) => s !== 'referral')),
};

// A variable is in-scope for the active (branch x channel) template pair. Single source of truth shared by the
// save-gate coverage checks (below) and the variable sidebar's grouping/Required badges, so they never disagree.
export function isVariableAllowed(v: ScopeVariable, branch: 'general' | 'project', channel: PromptChannel): boolean {
  if (!BRANCH_SCOPES[branch].has(v.scope)) return false;
  if (!v.channels.includes(toWireChannel(channel))) return false;
  return true;
}

export function missingRequiredVariables(
  variables: ScopeVariable[],
  branch: 'general' | 'project',
  channel: PromptChannel,
  systemMessage: string | null | undefined,
  userMessage: string | null | undefined
): string[] {
  const referenced = new Set([...tokensIn(systemMessage), ...tokensIn(userMessage)]);
  return variables
    .filter((v) => isVariableAllowed(v, branch, channel) && !referenced.has(v.name))
    .map((v) => v.name)
    .sort();
}

export function outOfScopeVariables(
  variables: ScopeVariable[],
  branch: 'general' | 'project',
  channel: PromptChannel,
  systemMessage: string | null | undefined,
  userMessage: string | null | undefined
): string[] {
  const allowed = new Set(variables.filter((v) => isVariableAllowed(v, branch, channel)).map((v) => v.name));
  const known = new Set(variables.map((v) => v.name));
  const referenced = new Set([...tokensIn(systemMessage), ...tokensIn(userMessage)]);
  return [...referenced].filter((name) => known.has(name) && !allowed.has(name)).sort();
}

export function unknownTokens(text: string | null | undefined, validNames: Iterable<string>): string[] {
  const valid = validNames instanceof Set ? validNames : new Set(validNames);
  const seen = new Set<string>();
  const unknown: string[] = [];
  for (const name of tokensIn(text)) {
    if (valid.has(name) || seen.has(name)) continue;
    seen.add(name);
    unknown.push(name);
  }
  return unknown;
}

/** Levenshtein-1 match, or null if none or >1 (an ambiguous suggestion is worse than none). */
export function closestName(name: string, validNames: Iterable<string>): string | null {
  let match: string | null = null;
  for (const candidate of validNames) {
    if (isDistanceOne(name, candidate)) {
      if (match) return null;
      match = candidate;
    }
  }
  return match;
}

function isDistanceOne(a: string, b: string): boolean {
  const lenDiff = a.length - b.length;
  if (lenDiff < -1 || lenDiff > 1) return false;
  if (a === b) return false;

  if (lenDiff === 0) {
    let diffs = 0;
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) diffs++;
      if (diffs > 1) return false;
    }
    return diffs === 1;
  }

  const longer = lenDiff === 1 ? a : b;
  const shorter = lenDiff === 1 ? b : a;
  let i = 0;
  let j = 0;
  let skipped = false;
  while (i < longer.length && j < shorter.length) {
    if (longer[i] === shorter[j]) {
      i++;
      j++;
    } else {
      if (skipped) return false;
      skipped = true;
      i++;
    }
  }
  return true;
}
