<template>
  <div class="rounded-md border bg-muted/40 px-3 py-2.5">
    <div class="mb-3 flex flex-wrap items-baseline gap-x-2 gap-y-1">
      <span class="text-sm font-medium">Validating prompt</span>
      <span class="text-xs text-muted-foreground">
        Generating sample emails and reviewing them for accuracy - usually 20-40 seconds.
      </span>
    </div>
    <Stepper :model-value="activeStep" class="w-full items-start gap-2">
      <StepperItem
        v-for="step in STEPS"
        :key="step.step"
        v-slot="{ state }"
        :step="step.step"
        class="flex w-full flex-col items-center gap-1.5 text-center"
      >
        <span
          class="flex h-7 w-7 items-center justify-center rounded-full border"
          :class="[
            state === 'completed' && 'border-primary bg-primary text-primary-foreground',
            state === 'active' && 'border-primary text-primary',
            state === 'inactive' && 'border-muted-foreground/30 text-muted-foreground',
          ]"
        >
          <Check v-if="state === 'completed'" class="h-4 w-4" />
          <Loader2Icon v-else-if="state === 'active'" class="h-4 w-4 animate-spin" />
          <Dot v-else class="h-4 w-4" />
        </span>
        <StepperTitle class="text-xs font-medium" :class="state === 'inactive' && 'text-muted-foreground'">
          {{ step.title }}
        </StepperTitle>
      </StepperItem>
    </Stepper>
  </div>
</template>

<script setup lang="ts">
import { Check, Dot, Loader2Icon } from 'lucide-vue-next';

const STEPS = [
  { step: 1, title: 'Checking variables' },
  { step: 2, title: 'Writing test emails' },
  { step: 3, title: 'Reviewing for accuracy' },
];

// One opaque request, so there's no real per-stage signal to follow: step 1 mirrors the client-side checks that
// already gated Save (so it lands done), and we move to the review step on a rough estimate to keep the wait alive.
const activeStep = ref(2);
let advanceTimer: ReturnType<typeof setTimeout> | undefined;

onMounted(() => {
  advanceTimer = setTimeout(() => {
    activeStep.value = 3;
  }, 15_000);
});

onUnmounted(() => {
  if (advanceTimer) clearTimeout(advanceTimer);
});
</script>
