<template>
  <FormItemWrapper :name="name" :is-required="true">
    <template #default="{ slots }">
      <div class="flex flex-col gap-1.5">
        <div class="flex items-center justify-between gap-2">
          <Label :for="name" class="text-sm font-medium">{{ label }} <span class="text-destructive">*</span></Label>
          <PromptTemplateEditorDialog
            :title="label"
            :description="description"
            :valid-names="validNames"
            :rendered="rendered"
            :model-value="slots.componentField.modelValue"
            @update:model-value="slots.componentField['onUpdate:modelValue']"
          />
        </div>
        <p class="text-sm text-muted-foreground">{{ description }}</p>
        <PromptTemplateEditor
          :id="name"
          :rows="rows"
          :model-value="slots.componentField.modelValue"
          :textarea-class="textareaClass"
          :valid-names="validNames"
          @update:model-value="slots.componentField['onUpdate:modelValue']"
          @focus="emit('focus', $event)"
        />
      </div>
    </template>
  </FormItemWrapper>
</template>

<script setup lang="ts">
defineProps<{
  name: string;
  label: string;
  description: string;
  rows: number;
  textareaClass: string;
  validNames: string[];
  rendered?: string | null;
}>();

const emit = defineEmits<{
  (e: 'focus', insert: (text: string) => void): void;
}>();
</script>
