import { updatePromptSettings } from '~/client';
import type { UpdatePromptSettingsResponse, PromptConfig } from '~/client';
import { promptValidationFailureFromError } from '~/utils/promptEditor/validationFailure';

export const useUpdateSettingsPrompt = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (body: PromptConfig): Promise<UpdatePromptSettingsResponse> =>
      updatePromptSettings({
        composable: '$fetch',
        body,
      }),
    onSuccess: () => {
      queryCache.invalidateQueries({ key: ['system-settings'] });
      queryCache.invalidateQueries({ key: ['prompt-editor-metadata'] });
      showToastSuccess('Prompt settings updated successfully');
    },
    onError: (error) => {
      // The prompt editor renders the structured 400 validation failure in its own modal;
      // a toast on top would double up. Toast only for other errors.
      if (!promptValidationFailureFromError(error)) showToastError(error);
    },
  });

  return {
    updateSettingsPrompt: mutateAsync,
    isUpdateSettingsPromptLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
