import { getUserList } from '~/client';
import { makePromptEditorSearch } from '~/queries/recruitment/promptEditorSearch';

export const useReferrerSearch = makePromptEditorSearch(
  'prompt-editor-referrer-search',
  (searchTerm) =>
    getUserList({ composable: '$fetch', body: { search_query: searchTerm, page: 1, size: 20 } }).then((r) => r.items),
  { listOnOpen: true }
);
