<script setup lang="ts">
import { useFormContext } from 'vee-validate';
import { parseDate, type DateValue } from '@internationalized/date';
import { ChevronDownIcon } from 'lucide-vue-next';
import type { PromptEditorOverrideValues } from '~/constants/validationSchemas/promptEditorOverride';
import { cn } from '@/lib/utils';
import { US_STATES } from '~/constants/usStates';
import { militaryServiceOptions } from '~/constants/account/militaryServiceOptions';
import { readinessStageOptions } from '~/constants/recruitment/readinessStageConfig';

const props = defineProps<{ projectTypeLabels: string[]; missingStepsLabels: string[] }>();

defineEmits<{ (e: 'clear-all'): void }>();

const open = ref(false);

// Wire value is the label itself, so value === name.
const projectTypeOptions = computed<SelectItem<string>[]>(() =>
  props.projectTypeLabels.map((label) => ({ name: label, value: label }))
);
const missingStepsOptions = computed<SelectItem<string>[]>(() =>
  props.missingStepsLabels.map((label) => ({ name: label, value: label }))
);

const { values, setFieldValue } = useFormContext<PromptEditorOverrideValues>();

const messageType = computed(() => values.message_type);
const isReferral = computed(() => values.is_referral);

// Server needs both dates or it drops the project from the preview; hint so the silent drop is expected.
const showProjectDateHint = computed(
  () =>
    values.message_type === 'PROJECT' &&
    values.target_project_name !== '' &&
    (values.target_project_start_date === '' || values.target_project_end_date === '')
);

// Registration is presence-only on the wire (user_id != null); the toggle stands in, registered = nil-UUID.
const NIL_USER_ID = '00000000-0000-0000-0000-000000000000';
const isRegistered = computed(() => values.contact_user_id != null);

function onRegisteredChange(v: boolean) {
  setFieldValue('contact_user_id', v ? NIL_USER_ID : null);
}

const stateOptions: SelectItem<string>[] = Object.entries(US_STATES).map(([value, name]) => ({ name, value }));

const targetProjectStartDateValue = computed<DateValue | undefined>(() =>
  values.target_project_start_date ? safeParse(values.target_project_start_date) : undefined
);
const targetProjectEndDateValue = computed<DateValue | undefined>(() =>
  values.target_project_end_date ? safeParse(values.target_project_end_date) : undefined
);
const campaignEndDateValue = computed<DateValue | undefined>(() =>
  values.campaign_end_date ? safeParse(values.campaign_end_date) : undefined
);

function safeParse(s: string): DateValue | undefined {
  try {
    return parseDate(s);
  } catch {
    return undefined;
  }
}

const additionalLanguagesText = computed(() => (values.contact_additional_languages ?? []).join('\n'));

function onAdditionalLanguagesChange(v: string | number) {
  setFieldValue('contact_additional_languages', linesFromText(v));
}
</script>

<style lang="scss" scoped></style>
