import type { PromptValidationResult, RecruitmentChannel, RecruitmentMessageType } from '~/client';

type PromptValidationSeverity = 'error' | 'warning';

export interface PromptValidationRuleEntry {
  label: string;
  blurb: string;
  fixHint: string;
  severity: PromptValidationSeverity;
}

// Keyed by Violation.rule_name - the judge rules (JudgeRuleId) plus the scope_coverage programmatic check.
export const promptValidationRuleConfig: Record<string, PromptValidationRuleEntry> = {
  fabricated_details: {
    label: 'Fabricated details',
    blurb: 'The email stated specifics that were not in the facts the model was given.',
    fixHint: 'Tell the model to use only the provided facts and never invent names, dates, rates, or programs.',
    severity: 'error',
  },
  referral_acknowledgement: {
    label: 'Referral acknowledgement',
    blurb: 'A referral email did not acknowledge the person who referred the contact.',
    fixHint: 'Make sure the referral branch thanks the contact for being referred.',
    severity: 'error',
  },
  internal_labels: {
    label: 'Internal labels leaked',
    blurb: 'Template scaffolding or instructions ended up in the email body.',
    fixHint: 'Keep section labels and instructions out of the text the model writes into the email.',
    severity: 'error',
  },
  scope_coverage: {
    label: 'Variable coverage',
    blurb: 'A branch is missing a required variable, or uses one that does not belong to it.',
    fixHint: 'Reference every variable the sidebar lists for this branch, and remove any that are not listed.',
    severity: 'error',
  },
  other: {
    label: 'Other issues',
    blurb: 'The reviewer flagged something outside the specific rules.',
    fixHint: 'Read the note and adjust the affected template.',
    severity: 'warning',
  },
};

const defaultRule: PromptValidationRuleEntry = { label: '', blurb: '', fixHint: '', severity: 'error' };

export function getPromptValidationRule(ruleName: string): PromptValidationRuleEntry {
  return promptValidationRuleConfig[ruleName] ?? { ...defaultRule, label: snakeCaseToCapitalizedCase(ruleName) };
}

export interface PromptConcern {
  text: string;
  meta: string; // "{rule label} · {persona}" (judge) or "{rule label}" (programmatic)
  severity: PromptValidationSeverity;
}

export interface ConcernGroup {
  branch: RecruitmentMessageType;
  channel: RecruitmentChannel;
  branchLabel: string;
  severity: PromptValidationSeverity; // worst concern in the group
  editTarget: string;
  concerns: PromptConcern[];
}

type GroupKey = `${RecruitmentMessageType}|${RecruitmentChannel}`;

const GROUP_ORDER: GroupKey[] = ['general|email', 'general|sms', 'project|email', 'project|sms'];
const FIELD_ANCHOR = /^(sms_)?(general|project)_(system|user)_message$/;
const groupDisplay = (branch: RecruitmentMessageType, channel: RecruitmentChannel): string =>
  `${branch === 'project' ? 'Project' : 'General'} ${channel === 'sms' ? 'SMS' : 'Email'}`;
const systemAnchor = (branch: RecruitmentMessageType, channel: RecruitmentChannel): string =>
  `${channel === 'sms' ? 'sms_' : ''}${branch}_system_message`;

// Collapse a validation result into per-(branch x channel) concern groups: the template pane that's broken,
// the plain-language problems in it, and where to jump to fix them. The judge already phrases each problem as
// one sentence, so we surface those directly instead of making the admin re-read the messages.
export function buildConcernGroups(result: PromptValidationResult): ConcernGroup[] {
  const byGroup = new Map<GroupKey, PromptConcern[]>();
  const editTarget = new Map<GroupKey, string>();
  const push = (key: GroupKey, concern: PromptConcern, preferredTarget: string | null) => {
    const list = byGroup.get(key) ?? [];
    list.push(concern);
    byGroup.set(key, list);
    if (preferredTarget && !editTarget.has(key)) editTarget.set(key, preferredTarget);
  };

  if (result.stage === 'judge') {
    // Dedupe identical (rule + explanation) within a pane and list the personas that hit it, so the same problem
    // across 3 probe messages reads as one line instead of three near-identical ones.
    const merged = new Map<string, { key: GroupKey; concern: PromptConcern; personas: string[] }>();
    for (const email of result.judged_emails ?? []) {
      if (email.compliant) continue;
      for (const v of email.violations) {
        const groupKey: GroupKey = `${email.message_type}|${email.channel}`;
        const key = `${groupKey}|${v.rule}|${v.explanation}`;
        const hit = merged.get(key);
        if (hit) {
          hit.personas.push(email.label);
          continue;
        }
        merged.set(key, {
          key: groupKey,
          concern: { text: v.explanation, meta: '', severity: getPromptValidationRule(v.rule).severity },
          personas: [email.label],
        });
      }
    }
    for (const { key, concern, personas } of merged.values()) {
      const [branch, channel] = key.split('|') as [RecruitmentMessageType, RecruitmentChannel];
      push(key, { ...concern, meta: `Seen in: ${personas.join(', ')}` }, systemAnchor(branch, channel));
    }
  } else {
    for (const v of result.violations ?? []) {
      const anchor = v.location ? FIELD_ANCHOR.exec(v.location) : null;
      const channel: RecruitmentChannel = anchor?.[1] ? 'sms' : 'email';
      const branch: RecruitmentMessageType =
        (anchor?.[2] as RecruitmentMessageType) ?? (v.location?.startsWith('project') ? 'project' : 'general');
      push(
        `${branch}|${channel}`,
        { text: v.message, meta: '', severity: getPromptValidationRule(v.rule_name).severity },
        anchor ? v.location! : null
      );
    }
  }

  return GROUP_ORDER.filter((key) => byGroup.has(key)).map((key) => {
    const [branch, channel] = key.split('|') as [RecruitmentMessageType, RecruitmentChannel];
    const concerns = byGroup.get(key) ?? [];
    return {
      branch,
      channel,
      branchLabel: groupDisplay(branch, channel),
      severity: concerns.some((c) => c.severity === 'error') ? 'error' : 'warning',
      editTarget: editTarget.get(key) ?? systemAnchor(branch, channel),
      concerns,
    };
  });
}
