import type { ComputedRef, Ref } from 'vue';
import { isEqual } from 'lodash';
import type { PromptConfig } from '~/client';
import type { PromptEditorOverrideValues } from '~/constants/validationSchemas/promptEditorOverride';

interface UsePromptDraftParams {
  values: PromptEditorOverrideValues;
  savedSlice: ComputedRef<PromptConfig | null>;
  hasHydrated: Ref<boolean>;
  toPromptSlice: (v: PromptEditorOverrideValues) => PromptConfig;
  restore: (slice: PromptConfig) => void;
  // Scope the draft per user so a logged-out admin's autosave never surfaces for the next admin on a shared browser.
  userId: string;
}

interface PromptDraftEnvelope {
  slice: PromptConfig;
  savedAt: string;
}

export function usePromptDraft({
  values,
  savedSlice,
  hasHydrated,
  toPromptSlice,
  restore,
  userId,
}: UsePromptDraftParams) {
  const storageKey = userId ? `prompt_editor_draft:${userId}` : 'prompt_editor_draft';

  // We read/write localStorage by hand rather than via useLocalStorage: VueUse dispatches a
  // StorageEvent on every write, and some browsers (e.g. extension-wrapped localStorage) reject
  // its storageArea - the throw lands before removeItem runs, so a cleared draft never actually
  // leaves storage and every write logs a console error.
  function readDraft(): PromptDraftEnvelope | null {
    if (!import.meta.client) return null;
    try {
      const raw = localStorage.getItem(storageKey);
      return raw ? (JSON.parse(raw) as PromptDraftEnvelope) : null;
    } catch {
      return null;
    }
  }

  function persistDraft(value: PromptDraftEnvelope | null) {
    if (!import.meta.client) return;
    try {
      if (value === null) localStorage.removeItem(storageKey);
      else localStorage.setItem(storageKey, JSON.stringify(value));
    } catch {
      // private mode / quota - the draft is best-effort, never block the editor on it
    }
  }

  const draft = ref<PromptDraftEnvelope | null>(readDraft());

  const showRestoreBanner = computed(() => {
    if (!draft.value || !savedSlice.value) return false;
    if (isEqual(draft.value.slice, savedSlice.value)) return false;
    // only while the form still shows the saved prompt - otherwise Restore re-applies the draft the form already holds (a no-op)
    return isEqual(toPromptSlice(values), savedSlice.value);
  });

  const draftSavedAt = computed(() => (draft.value?.savedAt ? new Date(draft.value.savedAt) : null));

  function onRestoreDraft() {
    if (!draft.value) return;
    restore(draft.value.slice);
  }

  function clearDraft() {
    draft.value = null;
    persistDraft(null);
  }

  // Skip when slice == saved: hydration moves the watched slice off cold defaults, which would else overwrite a real prior-session draft with a no-op and kill Restore.
  watchDebounced(
    () => toPromptSlice(values),
    (slice) => {
      if (!hasHydrated.value || isEqual(slice, savedSlice.value)) return;
      const envelope: PromptDraftEnvelope = { slice, savedAt: new Date().toISOString() };
      draft.value = envelope;
      persistDraft(envelope);
    },
    { debounce: 1000, deep: true }
  );

  return { showRestoreBanner, onRestoreDraft, onDiscardDraft: clearDraft, clearDraft, draftSavedAt };
}
