<template>
  <div
    v-if="previewContextReady"
    class="flex flex-wrap items-center gap-x-2 gap-y-1.5 rounded-md border bg-muted/40 px-3 py-2 text-sm"
  >
    <span class="text-muted-foreground">Config short summary: </span>
    <span class="font-medium">{{ contactDisplayName ?? 'No contact' }}</span>
    <Badge size="sm" :variant="values.contact_user_id ? 'success' : 'default'">
      {{ values.contact_user_id ? 'Registered' : 'Unregistered' }}
    </Badge>
    <span v-if="values.contact_state" class="text-muted-foreground">{{ values.contact_state }}</span>
    <Badge size="sm" variant="info">{{ previewModeLabel }}</Badge>
    <Badge v-if="readinessChip" size="sm" :variant="readinessChip.variant">{{ readinessChip.label }}</Badge>
    <template v-if="values.message_type === 'PROJECT'">
      <span class="text-muted-foreground">&middot;</span>
      <span class="text-muted-foreground">{{ projectStripLabel }}</span>
      <Badge v-if="tierChip" size="sm" :variant="tierChip.variant">{{ tierChip.label }}</Badge>
      <span v-if="distanceLabel" class="text-muted-foreground">{{ distanceLabel }}</span>
      <span v-if="values.rate_amount" class="text-muted-foreground">{{ values.rate_amount }}</span>
    </template>
    <span v-if="isResolving" class="ml-auto flex items-center gap-1 text-xs text-muted-foreground">
      <Loader2Icon class="h-3.5 w-3.5 min-h-3.5 min-w-3.5 animate-spin" />
      Updating config...
    </span>
  </div>
</template>

<script setup lang="ts">
import { useFormContext } from 'vee-validate';
import { Loader2Icon } from 'lucide-vue-next';
import type { PromptEditorOverrideValues } from '~/constants/validationSchemas/promptEditorOverride';
import { getReadinessStage } from '~/constants/recruitment/readinessStageConfig';
import { getDistanceClassification } from '~/constants/recruitment/distanceClassificationConfig';

const props = defineProps<{
  previewContextReady: boolean;
  isResolving: boolean;
  contactDisplayName: string | null;
  selectedProjectLabel: string | null;
}>();

const { values } = useFormContext<PromptEditorOverrideValues>();

const previewModeLabel = computed(() =>
  values.is_referral ? 'General + Referral' : values.message_type === 'PROJECT' ? 'Project' : 'General'
);

const readinessChip = computed(() => (values.readiness_stage ? getReadinessStage(values.readiness_stage) : null));

const tierChip = computed(() => {
  if (values.message_type !== 'PROJECT') return null;
  if (!values.distance_classification) return { label: 'No location', variant: 'default' as const };
  return getDistanceClassification(values.distance_classification);
});

// A sub-mile Local contact rounds to "0 mi", which reads like "no location" - show "< 1 mi" instead.
const distanceLabel = computed(() => {
  if (values.distance_miles === null) return null;
  return values.distance_miles < 1 ? '< 1 mi' : `${values.distance_miles.toFixed(0)} mi`;
});

const projectStripLabel = computed(() => {
  if (props.selectedProjectLabel) return props.selectedProjectLabel;
  if (values.target_project_name) return `${values.target_project_name} (sample)`;
  return 'General settings';
});
</script>

<style lang="scss" scoped></style>
