<template>
  <Dialog v-model:open="open">
    <DialogTrigger as-child>
      <Button type="button" variant="ghost" size="sm" class="gap-1.5">
        <Maximize2Icon class="h-3.5 w-3.5" />
        Expand
      </Button>
    </DialogTrigger>
    <DialogScrollContent class="max-w-5xl">
      <DialogHeader>
        <DialogTitle>{{ title }}</DialogTitle>
        <DialogDescription>{{ description }}</DialogDescription>
      </DialogHeader>
      <div class="grid gap-4 lg:grid-cols-2">
        <div class="flex min-w-0 flex-col gap-1">
          <Label class="text-xs font-semibold text-muted-foreground">Template</Label>
          <PromptTemplateEditor
            :model-value="modelValue"
            :valid-names="validNames"
            textarea-class="font-mono min-h-[60vh]"
            @update:model-value="(v: string) => emit('update:modelValue', v)"
          />
        </div>
        <div class="flex min-w-0 flex-col gap-1">
          <Label class="text-xs font-semibold text-muted-foreground">Rendered preview</Label>
          <pre class="min-h-[60vh] overflow-auto whitespace-pre-wrap rounded-md border bg-muted p-3 text-sm">{{
            rendered || 'No render yet'
          }}</pre>
        </div>
      </div>
    </DialogScrollContent>
  </Dialog>
</template>

<script setup lang="ts">
import { Maximize2Icon } from 'lucide-vue-next';

defineProps<{
  modelValue?: string;
  validNames: string[];
  title: string;
  description?: string;
  rendered?: string | null;
}>();

const emit = defineEmits<{
  (e: 'update:modelValue', payload: string): void;
}>();

const open = ref(false);
</script>
