<template>
  <div class="flex flex-col gap-1.5">
    <div class="flex flex-wrap gap-2">
      <TooltipProvider :delay-duration="300">
        <Tooltip v-for="preset in presets" :key="preset.name">
          <TooltipTrigger as-child>
            <!-- Disabled <button> swallows pointer events; wrap in a span so the tooltip still gets hover. -->
            <span>
              <Button
                type="button"
                variant="outline"
                :disabled="isGated(preset) || disabled"
                :class="{ 'border-primary': selectedName === preset.name }"
                @click="$emit('select', preset.name)"
              >
                {{ preset.label }}
              </Button>
            </span>
          </TooltipTrigger>
          <TooltipContent>
            {{ isGated(preset) ? GATED_REASON : preset.description }}
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    </div>
    <!-- Tooltips are hover-only (invisible on touch), so mirror the selected preset's line inline too. -->
    <p v-if="selectedName" class="text-xs text-muted-foreground">{{ describeSelected() }}</p>
  </div>
</template>

<script setup lang="ts">
import { fullyOnboardedReadinessStages } from '~/constants/recruitment/readinessStageConfig';

import type { PresetMetadata, PreviewPresetName } from '~/client';

const props = defineProps<{
  presets: PresetMetadata[];
  selectedName: PreviewPresetName | null;
  messageType: 'GENERAL' | 'PROJECT';
  disabled?: boolean;
}>();
defineEmits<{ (e: 'select', name: PreviewPresetName): void }>();

const GATED_REASON = 'General recruitment never targets fully-onboarded contacts.';

// Gate fully-onboarded personas on General by readiness_stage, not name (that funnel is cold/in-progress only).
function isGated(preset: PresetMetadata): boolean {
  return props.messageType === 'GENERAL' && fullyOnboardedReadinessStages.has(preset.readiness_stage);
}

// The selected preset's description (or its gated reason). Plain function, not a computed, so the gating unit
// test can mount this in plain vitest without the app's Nuxt auto-imports.
function describeSelected(): string {
  const preset = props.presets.find((p) => p.name === props.selectedName);
  if (!preset) return '';
  return isGated(preset) ? GATED_REASON : preset.description;
}
</script>
