<template>
  <p v-if="!hasActiveField" class="text-xs text-muted-foreground mb-2">
    Click into a message field, then a variable to insert it.
  </p>
  <p v-if="hasMissingRequired" class="text-xs text-destructive mb-2">
    Every variable must be used in this branch's templates. Insert the ones marked Required to save.
  </p>
  <TooltipProvider :delay-duration="300">
    <div class="flex flex-col gap-4">
      <div v-for="(scope, scopeName) in groupedVariables" :key="scopeName" class="flex flex-col gap-1">
        <h3 class="text-xs font-semibold uppercase text-muted-foreground">{{ scopeName }}</h3>
        <Tooltip v-for="v in scope" :key="v.name">
          <TooltipTrigger as-child>
            <button
              type="button"
              class="flex flex-col items-start gap-1 rounded-md border p-2 text-left hover:bg-accent w-full"
              :class="{ 'border-destructive': !isUsed(v.name) }"
              @mousedown.prevent="handleInsert(v.name)"
              @keydown.enter.prevent="handleInsert(v.name)"
            >
              <div class="flex items-center justify-between gap-2 w-full">
                <span class="text-xs font-mono">{{ '{' + v.name + '}' }}</span>
                <div class="flex items-center gap-1">
                  <Badge v-if="!isUsed(v.name)" size="sm" variant="destructive">Required</Badge>
                  <Badge size="sm" :variant="getStatusVariant(v.name)">{{ getStatus(v.name) }}</Badge>
                </div>
              </div>
              <div class="text-xs text-muted-foreground">{{ truncate(getResolvedValue(v.name)) }}</div>
            </button>
          </TooltipTrigger>
          <TooltipContent>
            <div class="max-w-xs whitespace-pre-wrap break-words text-xs">
              <div class="font-semibold mb-1">{{ v.description }}</div>
              <div>{{ getResolvedValue(v.name) || '(empty)' }}</div>
            </div>
          </TooltipContent>
        </Tooltip>
      </div>
    </div>
  </TooltipProvider>
</template>

<script setup lang="ts">
import { type BadgeVariants } from '~/components/ui/badge';
import type { PromptVariables, VariableSchema } from '~/client';
import { isVariableAllowed, toWireMessageType, type PromptChannel } from '~/utils/promptEditor/placeholders';

type VariableStatus = 'From source' | 'Not set';

const props = defineProps<{
  variables: VariableSchema[];
  placeholderValues: PromptVariables | null;
  hasActiveField: boolean;
  messageType: 'GENERAL' | 'PROJECT';
  channel: PromptChannel;
  usedNames: string[];
}>();

const emit = defineEmits<{
  (e: 'insert', name: string): void;
}>();

const usedSet = computed(() => new Set(props.usedNames));

function getResolvedValue(name: string): string {
  if (!props.placeholderValues) return '';
  const values = props.placeholderValues as unknown as Record<string, unknown>;
  const raw = values[name];
  return raw == null ? '' : String(raw);
}

function truncate(s: string, n = 60): string {
  return s.length > n ? s.slice(0, n) + '...' : s;
}

function getStatus(name: string): VariableStatus {
  const v = getResolvedValue(name);
  return v ? 'From source' : 'Not set';
}

function getStatusVariant(name: string): BadgeVariants {
  return getStatus(name) === 'Not set' ? 'default' : 'success';
}

function isUsed(name: string): boolean {
  return usedSet.value.has(name);
}

function handleInsert(name: string) {
  emit('insert', name);
}

// Group only the variables in-scope for the active (branch x channel) pair, via the same allowance the save-gate
// uses - so the sidebar's Required badges never demand a token the save would then reject as out-of-scope.
const groupedVariables = computed(() => {
  const branch = toWireMessageType(props.messageType);
  const groups: Record<string, VariableSchema[]> = {};
  for (const v of props.variables) {
    if (!isVariableAllowed(v, branch, props.channel)) continue;
    if (!groups[v.scope]) groups[v.scope] = [];
    groups[v.scope].push(v);
  }
  return groups;
});

const hasMissingRequired = computed(() =>
  Object.values(groupedVariables.value).some((scope) => scope.some((v) => !isUsed(v.name)))
);
</script>

<style lang="scss" scoped></style>
