import { getStaffingContactList } from '~/client';
import { makePromptEditorSearch } from '~/queries/recruitment/promptEditorSearch';

export const useStaffingContactSearch = makePromptEditorSearch('prompt-editor-contact-search', (searchTerm) =>
  getStaffingContactList({ composable: '$fetch', query: { search_query: searchTerm, page: 1, size: 20 } }).then(
    (r) => r.items
  )
);
