import type { PreviewCampaign, PreviewContext, PreviewProject } from '~/client';
import type { PromptEditorOverrideValues } from '~/constants/validationSchemas/promptEditorOverride';

export interface FePriorBody {
  subject: string;
  content: string;
}

export function toPreviewContext(form: PromptEditorOverrideValues): PreviewContext {
  const referrer =
    form.is_referral && form.referrer_user_id !== ''
      ? {
          user_id: form.referrer_user_id,
          first_name: form.referrer_first_name,
          last_name: form.referrer_last_name,
        }
      : null;

  const target_project: PreviewProject | null =
    form.message_type === 'PROJECT' && form.target_project_name !== ''
      ? {
          name: form.target_project_name,
          description: form.target_project_description,
          locations: form.target_project_locations,
          start_date: form.target_project_start_date || null,
          end_date: form.target_project_end_date || null,
          public_url: form.target_project_public_url || null,
          project_type: form.target_project_project_type,
        }
      : null;

  const campaign: PreviewCampaign | null =
    form.message_type === 'PROJECT'
      ? {
          selling_points: form.campaign_selling_points ?? '',
          latest_news: form.campaign_latest_news ?? '',
          custom_notes: form.campaign_custom_notes ?? '',
          end_date: form.campaign_end_date || null,
          target_project,
        }
      : null;

  return {
    contact: {
      first_name: form.contact_first_name,
      last_name: form.contact_last_name || null,
      preferred_name: form.contact_preferred_name || null,
      state: form.contact_state || null,
      city: form.contact_city || null,
      user_id: form.contact_user_id,
      additional_languages: form.contact_additional_languages,
      military_status: form.contact_military_status || null,
      total_projects: form.contact_total_projects,
      source: form.contact_source,
    },
    readiness_stage: form.readiness_stage,
    missing_steps: form.missing_steps,
    contact_bio: form.contact_bio || null,
    military_service: form.military_service,
    referral_source: form.referral_source || null,
    rate_amount: form.rate_amount,
    increased_rate_amount: form.increased_rate_amount,
    increased_rate_threshold: form.increased_rate_threshold,
    // Computed server-side; round-tripped only so the request mirrors the resolved context.
    distance_classification: form.distance_classification,
    distance_miles: form.distance_miles,
    referrer,
    campaign,
    prior_bodies: form.prior_bodies.map((b) => ({ subject: b.subject, content: b.content })),
    prior_project_names: form.prior_project_names,
    cross_promos: form.cross_promos,
  };
}
